import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import classNames from 'classnames'

import HighlighterTextFieldItem from '../HighlighterTextFieldItem/HighlighterTextFieldItem'

import styles from './HighlighterTextField.module.css'

type HighlighterTextFieldProps = {
  line: string
  type?: string
  index: number
  isIncludedLine?: boolean
  onSelect?: (item: SelectItem) => void
}

function HighlighterTextFieldToken({
  line,
  type,
  index,
  onSelect,
  isIncludedLine,
}: HighlighterTextFieldProps) {
  const isUnkownType = !type
  const isElementRef = type === 'ref'
  const isTypingRef = type === 'typing'
  const isTyping = Boolean(isTypingRef && isIncludedLine)
  const elementClassName = styles[type as keyof typeof styles] ?? ''
  const stylesClasses = classNames(styles.token, {
    [elementClassName]: isIncludedLine || isElementRef,
  })
  const textElemenet = line.replace(/^%|%$/g, '')
  const PrefixLineElement = <span className={styles.prefix}>{'%'}</span>
  const isShowPrefix = isElementRef || isTypingRef
  const LineElement = (
    <span className={stylesClasses} key={index}>
      {isShowPrefix && PrefixLineElement}
      {textElemenet}
      {isElementRef && PrefixLineElement}
    </span>
  )
  const key = isTyping ? `type-${index}` : `element-${index}`

  if (isUnkownType) {
    return line
  }

  if (!isElementRef && !isTyping) {
    return LineElement
  }

  return (
    <HighlighterTextFieldItem
      key={key}
      line={line}
      isElement={isElementRef}
      isTyping={isTyping}
      onSelect={onSelect}
    >
      {LineElement}
    </HighlighterTextFieldItem>
  )
}

export default HighlighterTextFieldToken
