import {produce} from 'immer'

import {useEffect, useRef, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../../../hooks/react-redux'
import SuggestionMessage from '../../../../../../../components/SuggestionMessage/SuggestionMessage'
import {usePipelineId} from '../../../../../../../hooks/pipeline'
import {SuggestionType} from '../../../../../../../types'
import {useJobId} from '../../../../../../EditPipelinePage.hooks'
import {
  getDraft,
  getDraftJobs,
  isSuggestionSkipped,
  getSkippedSuggestions,
} from '../../../../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineForm,
  suggestions,
} from '../../../../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../../../../slices/EditPipelinePage.slices.types'
import {addIntegration} from '../../../../../Integrations/Integrations.actions'
import {IntegrationType} from '../../../../../Integrations/Integrations.consts'
import {jobIntegrationsSettingsBlockId} from '../../../../JobIntegrations/JobIntegrations'
import type {SmartDetectorProps} from '../SmartDetectors.types'

function CliDockerLogin({name, value, stepIndex, focused}: SmartDetectorProps) {
  const jobId = useJobId()!
  const id = usePipelineId()
  const stepId = `step-${jobId}-${stepIndex + 1}`
  const stepList = useAppSelector(state => getDraftJobs(state, id)?.[jobId]?.steps)
  const skippedSuggestionList = useAppSelector(state => getSkippedSuggestions(state, stepId))
  const isSkipped = useAppSelector(state =>
    isSuggestionSkipped(state, stepId, SuggestionType.CLI_DOCKER_LOGIN),
  )
  const hasEnabledDockerIntegraion = useAppSelector(state => {
    const enabledIntegrations = getDraftJobs(state, id)?.[jobId]?.integrations
    if (enabledIntegrations == null || enabledIntegrations.length === 0) {
      return null
    }
    const allIntegrations = getDraft(state, id)?.integrations
    const deletedIntegrations = state.pipelines.pipelineDraft[id]?.deleted?.integrations
    return allIntegrations?.some(
      integration =>
        integration.type === IntegrationType.DOCKER &&
        enabledIntegrations.includes(integration.parameters.displayName!) &&
        !deletedIntegrations?.includes(integration.id!),
    )
  })
  const [isDockerFormOpened, setIsDockerFormOpened] = useState(false)
  const dispatch = useAppDispatch()
  const match = value.match(/^.*docker login(.*)(?:\n([\s\S]*))?$/)
  const script = match?.[2] ?? ''
  const isAddingDocker = useRef(false)
  const visible =
    !hasEnabledDockerIntegraion && !!match && !isSkipped && !isDockerFormOpened && focused

  useEffect(() => {
    if (hasEnabledDockerIntegraion && isAddingDocker.current) {
      dispatch(
        pipelineDraft.actions.setSteps({
          id,
          jobId,
          steps: produce(stepList ?? [], draft => {
            const step = draft[stepIndex]
            step[name] = script
          }),
        }),
      )
      isAddingDocker.current = false
    }
  }, [dispatch, hasEnabledDockerIntegraion, id, jobId, name, script, stepIndex, stepList])

  const username = match?.[1]?.match(/(?:-u|--username)[=\s](\S+)/)?.[1] ?? ''
  return (
    <SuggestionMessage
      message={`We detected docker login. Add Docker integration instead? This will securely run 'docker login' while keeping your credentials safe.`}
      actionText="Add"
      visible={visible}
      onCancelClick={() => {
        dispatch(
          suggestions.actions.skip({
            id: stepId,
            values: produce(skippedSuggestionList ?? [], draft => {
              if (!draft.includes(SuggestionType.CLI_DOCKER_LOGIN)) {
                draft.push(SuggestionType.CLI_DOCKER_LOGIN)
              }
            }),
          }),
        )
      }}
      onActionClick={() => {
        isAddingDocker.current = true
        const integrationId = dispatch(
          addIntegration({
            pipelineId: id,
            jobId,
            type: IntegrationType.DOCKER,
            parameters: {username},
          }),
        )
        dispatch(
          collapsedBlocks.actions.toggle({id: jobIntegrationsSettingsBlockId, collapsed: false}),
        )
        dispatch(
          pipelineForm.actions.open({
            pipelineId: id,
            jobId,
            id: integrationId,
            type: FormType.PIPELINE_INTEGRATION,
            isAdd: true,
          }),
        )
        setIsDockerFormOpened(true)
      }}
    />
  )
}

export default CliDockerLogin
