import type {AppThunk} from '../../../../../../actions/types'
import type {AddIntegrationPayload} from '../../slices/EditPipelinePage.integration.slice'
import {pipelineDraft} from '../../slices/EditPipelinePage.slices'

import {generateFreeIntegrationName} from './Integration.selectors'

export const addIntegration =
  (payload: AddIntegrationPayload): AppThunk<string> =>
  (dispatch, getState) => {
    const {pipelineId, type, parameters} = payload
    const displayName = generateFreeIntegrationName(getState(), pipelineId, type)
    dispatch(
      pipelineDraft.actions.addIntegration({
        ...payload,
        parameters: {...parameters, displayName},
      }),
    )
    return displayName
  }
