import {StepTypes} from '../../../../types'

import {gradleStepPreset, mavenStepPreset, nodeStepPreset} from './JobSteps.const'

export function getStepPreset(type: string | undefined) {
  switch (type) {
    case StepTypes.NODE:
      return nodeStepPreset
    case StepTypes.MAVEN:
      return mavenStepPreset
    case StepTypes.GRADLE:
      return gradleStepPreset

    default:
      return null
  }
}
