import type {State} from '../../../../../../reducers/types'
import type {PipelineId} from '../../../../../../types'
import {generateFreeName} from '../../../utils/generateFreeName'
import {getDraft} from '../../EditPipelinePage.selectors'

import {integrations} from './Integrations.consts'

export function generateFreeIntegrationName(state: State, pipelineId: PipelineId, type: string) {
  const usedNames =
    getDraft(state, pipelineId)?.integrations?.map(({parameters}) => parameters.displayName) ?? []
  const base = integrations[type].displayName
  return generateFreeName({
    getName: i => (i > 0 ? `${base} ${i}` : base),
    usedNames,
    errorMessage: `Error while generating new integration name`,
  })
}
