import classNames from 'classnames'

import useRunnerIconButton from './useRunnerIconButton'

import styles from './RunnerIconButton.module.css'

type RunnerIconButtonProps = {
  icon?: string
  label?: string
  value?: string
  selected?: boolean
  onClick?: (value: string) => void
  className?: string
}

function RunnerIconButton({
  icon,
  label,
  value = '',
  onClick,
  className,
  selected,
}: RunnerIconButtonProps) {
  const {Icon} = useRunnerIconButton(icon)
  const buttonClickHandler = () => onClick?.(value)
  const buttonClassNames = classNames(styles.button, {
    [styles.selected]: selected,
  })
  const iconClassNames = classNames(styles.icon, className, {
    [styles.iconHover]: onClick,
  })

  return (
    <div role="presentation" onClick={buttonClickHandler} className={buttonClassNames}>
      <div className={iconClassNames}>
        <Icon />
      </div>
      {label && <div className={styles.label}>{label}</div>}
    </div>
  )
}

export default RunnerIconButton
