import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {noop} from '../../../../../../utils/empty'
import EditButton from '../../../components/EditButton/EditButton'
import {DisabledContext} from '../../../contexts/DisabledContext'
import {usePipelineId} from '../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../hooks/usePermissionCanEditPipeline'
import {useIsDebugRunning, useJobId} from '../../EditPipelinePage.hooks'
import {isPipelineFormOpened} from '../../EditPipelinePage.selectors'
import {pipelineForm} from '../../slices/EditPipelinePage.slices'
import {FormType} from '../../slices/EditPipelinePage.slices.types'

import NameSectionForm from './NameSectionForm'

import styles from './NameSection.module.css'

type Props = {
  name: string
  'aria-label'?: string
  onNameChange: (value: string) => void
  onConfirm?: () => void
  children?: React.ReactNode
  isJob?: boolean
}

function NameSection({
  name,
  onNameChange,
  onConfirm,
  'aria-label': ariaLabel,
  children,
  isJob,
}: Props) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const isDisabled = React.useContext(DisabledContext)
  const isDebugRunning = useIsDebugRunning()
  const isReadonly = isDebugRunning || (!canEditPipeline && !isJob)
  const pipelineId = usePipelineId()
  const jobId = useJobId()
  const formParams = {pipelineId, jobId, type: FormType.NAME}
  const isEditing = useAppSelector(state => isPipelineFormOpened(state, formParams))
  const dispatch = useAppDispatch()
  const enableEditing = () => dispatch(pipelineForm.actions.open(formParams))
  const disableEditing = () => dispatch(pipelineForm.actions.close(formParams))

  const handleEditClick = () => {
    enableEditing()
  }

  return (
    <div className={styles.nameSection}>
      {!isEditing ? (
        <>
          <div
            role="presentation"
            onClick={isReadonly ? noop : handleEditClick}
            className={styles.heading}
          >
            <H2 className={styles.name} title={name}>
              {name}
            </H2>
            {!isReadonly && (
              <EditButton
                iconClassName={styles.editIcon}
                className={styles.edit}
                disabled={isDisabled}
              />
            )}
          </div>
          {children}
        </>
      ) : (
        <NameSectionForm
          currentName={name}
          aria-label={ariaLabel}
          onConfirmClick={() => {
            disableEditing()
            onConfirm?.()
          }}
          onNameChange={onNameChange}
        />
      )}
    </div>
  )
}

export default NameSection
