import HighlighterTextField from '../../../../../components/HighlighterTextField/HighlighterTextField'
import useParametersControl from '../../../../../contexts/ParametersControl/useParametersControl'

import type {PipelineParameterFormFieldsetProps} from './PipelineParameterFormFieldset.types'

import styles from './PipelineParameterFormFieldset.module.css'

import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

function PipelineParameterFormFieldset({
  savedName = '',
  inputRef,
}: PipelineParameterFormFieldsetProps) {
  const {
    parameterName,
    parameterValue,
    parameterNameErrorMessage,
    parameterValueErrorMessage,
    valueHighlightSpot,
    changeNameHandler,
    changeValueHandler,
  } = useParametersControl(savedName)

  return (
    <div className={styles.pipelineParameterWrapForm}>
      <div className={styles.pipelineParameterFormInput}>
        <Input
          placeholder={'Parameter Name'}
          onChange={changeNameHandler}
          inputClassName={styles.textArea}
          value={parameterName}
          size={Size.FULL}
          aria-label="Parameter Name"
          error={parameterNameErrorMessage}
          autoComplete="off"
          spellCheck={false}
          multiline
          inputRef={inputRef}
        />
      </div>
      <div className={styles.pipelineParameterFormInput}>
        <HighlighterTextField
          spot={valueHighlightSpot}
          error={parameterValueErrorMessage}
          value={parameterValue}
          placeholder={'Value'}
          multiline
          autoComplete="off"
          data-test="highlighter-text-field"
          onChange={changeValueHandler}
        />
      </div>
    </div>
  )
}

export default PipelineParameterFormFieldset
