import {useCallback, useMemo, useState} from 'react'

import {maxListItemLimitAmount} from './PipelineParametersSettingsBlock.consts'

function usePipelineParametersSettingsBlock(parameters: Record<string, string | undefined>) {
  const parametersKeys = useMemo(() => Object.keys(parameters), [parameters])
  const parametersLength = parametersKeys.length
  const [listItemLimit, setListItemLimit] = useState<number>(maxListItemLimitAmount)
  const isShowMoreButton = parametersLength > maxListItemLimitAmount
  const clickShowMoreButtonHandler = useCallback(() => {
    const itemLimit =
      listItemLimit === maxListItemLimitAmount ? parametersLength : maxListItemLimitAmount

    setListItemLimit(itemLimit)
  }, [listItemLimit, parametersLength])
  const isBlockExpanded = listItemLimit === parametersLength

  return {
    listItemLimit,
    parametersKeys,
    isShowMoreButton,
    isBlockExpanded,
    clickShowMoreButtonHandler,
  }
}

export default usePipelineParametersSettingsBlock
