import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import PipelineParameterFormFieldset from '../PipelineParameterFormFieldset/PipelineParameterFormFieldset'

import type {PipelineParameterFormProps} from './PipelineParameterForm.types'
import usePipelineParameterForm from './usePipelineParameterForm'

function PipelineParameterForm({savedName, inputRef, onDelete}: PipelineParameterFormProps) {
  const {isFormInvalid} = usePipelineParameterForm(savedName)

  return (
    <EditSettingsForm inline onDeleteClick={onDelete} disabled={isFormInvalid}>
      <PipelineParameterFormFieldset inputRef={inputRef} savedName={savedName} />
    </EditSettingsForm>
  )
}

export default PipelineParameterForm
