import {useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {getEmptyHash} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import {validateAllForms} from '../../../EditPipelinePage.actions'
import {useJobId} from '../../../EditPipelinePage.hooks'
import {
  getDraftJobs,
  getPipeline,
  getPipelineErrorMessage,
} from '../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

import {jobOutputParametersSettingsBlockId} from './JobOutputParameters.consts'

function useJobOutputParametersStore() {
  const pipelineId = usePipelineId()
  const jobId = useJobId() ?? ''
  const dispatch = useAppDispatch()
  const formSpotParamId = useMemo(
    () => ({
      jobId,
      pipelineId,
      type: FormType.JOB_OUTPUT_PARAMETER,
    }),
    [jobId, pipelineId],
  )
  const formErrorSpotId = useMemo(
    () => ({
      jobId,
      pipelineId,
      formType: FormType.JOB_OUTPUT_PARAMETER,
    }),
    [jobId, pipelineId],
  )
  const jobOutputParameters =
    useAppSelector(state => getDraftJobs(state, pipelineId)?.[jobId]?.['output-parameters']) ??
    getEmptyHash()
  const jobOutputParametersKeys = useMemo(
    () => Object.keys(jobOutputParameters),
    [jobOutputParameters],
  )
  const jobOutputParametersLength = jobOutputParametersKeys.length
  const addJobOutputParameterHandler = useCallback(() => {
    dispatch(pipelineDraft.actions.addJobOutputParameter({pipelineId, jobId}))
    dispatch(
      collapsedBlocks.actions.toggle({id: jobOutputParametersSettingsBlockId, collapsed: false}),
    )
  }, [dispatch, jobId, pipelineId])
  const deletedJobOutputParameters = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.jobOutputParameters,
    shallowEqual,
  )
  const addedJobOutputParameters = useAppSelector(
    state => getPipeline(state, pipelineId)?.added?.jobOutputParameters,
  )
  const jobOutputParametersFormErrorMessage = useAppSelector(
    getPipelineErrorMessage(formErrorSpotId),
  )
  const clearAddedJobOutputParametersHandler = useCallback(() => {
    Object.keys(addedJobOutputParameters ?? {}).forEach(key =>
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: key,
        }),
      ),
    )
    dispatch(pipelineDraft.actions.clearAddedJobOutputParameters({pipelineId, jobId}))
  }, [addedJobOutputParameters, dispatch, formErrorSpotId, jobId, pipelineId])
  const getIsJobOutputParametersValid = useCallback(
    () =>
      dispatch(
        validateAllForms(
          pipelineId,
          form =>
            form.type === FormType.JOB_OUTPUT_PARAMETER &&
            form.jobId === jobId &&
            addedJobOutputParameters?.[form.id!] === true,
        ),
      ),
    [addedJobOutputParameters, dispatch, jobId, pipelineId],
  )
  const jobOutputParameterMultiplyConfirmHandler = useCallback(
    () => dispatch(pipelineDraft.actions.applyAddedJobOutputParameters(pipelineId)),
    [dispatch, pipelineId],
  )
  const confirmParametersHandler = useCallback(
    (isValid: boolean, parameterName: string) => {
      if (isValid) {
        dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
      }
    },
    [dispatch, formSpotParamId],
  )
  const deleteParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(
        pipelineDraft.actions.deleteJobOutputParameter({
          pipelineId,
          jobId,
          savedName: parameterName,
        }),
      )
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: parameterName,
        }),
      )
      dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
    },
    [dispatch, formErrorSpotId, formSpotParamId, jobId, pipelineId],
  )
  const restoreParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(
        pipelineDraft.actions.restoreJobOutputParameter({
          pipelineId,
          jobId,
          savedName: parameterName,
        }),
      )
    },
    [dispatch, jobId, pipelineId],
  )
  const changeNameHandler = useCallback(
    (name: string, savedName: string) => {
      dispatch(
        pipelineDraft.actions.renameJobOutputParameter({
          pipelineId,
          name,
          savedName,
        }),
      )
    },
    [dispatch, pipelineId],
  )
  const changeValueHandler = useCallback(
    (value: string, parameterName: string) => {
      dispatch(
        pipelineDraft.actions.setJobOutputParameter({
          pipelineId,
          jobId,
          savedName: parameterName,
          value,
        }),
      )
    },
    [dispatch, jobId, pipelineId],
  )
  const renamedJobOutputParameters = (useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.renamed?.jobOutputParameters,
  ) ?? getEmptyHash()) as Record<string, string>
  const existingJobParameters = useMemo(
    () =>
      jobOutputParametersKeys.filter(
        jobParameter => !deletedJobOutputParameters?.includes(jobParameter),
      ),
    [deletedJobOutputParameters, jobOutputParametersKeys],
  )
  const summaryNote = useMemo(
    () =>
      jobOutputParametersKeys
        .filter(key => !deletedJobOutputParameters?.includes(key))
        .map(key => `${renamedJobOutputParameters?.[key] ?? key}=${jobOutputParameters[key]}`)
        .join(', '),
    [
      deletedJobOutputParameters,
      jobOutputParameters,
      jobOutputParametersKeys,
      renamedJobOutputParameters,
    ],
  )
  const existingJobParametersLength = existingJobParameters.length

  return {
    summaryNote,
    jobOutputParameters,
    jobOutputParametersKeys,
    jobOutputParametersLength,
    deletedJobOutputParameters,
    getIsJobOutputParametersValid,
    addJobOutputParameterHandler,
    existingJobParametersLength,
    jobOutputParametersFormErrorMessage,
    jobOutputParameterMultiplyConfirmHandler,
    clearAddedJobOutputParametersHandler,

    formSpotParamId,
    formErrorSpotId,
    renamedJobOutputParameters,
    changeNameHandler,
    changeValueHandler,
    confirmParametersHandler,
    deleteParametersHandler,
    restoreParametersHandler,
  }
}

export default useJobOutputParametersStore
