import {produce} from 'immer'

import {memo} from 'react'

import SuggestionMessage from '../../../../../../../components/SuggestionMessage/SuggestionMessage'
import {usePipelineId} from '../../../../../../../hooks/pipeline'
import {StepTypes, SuggestionType} from '../../../../../../../types'
import {useJobId} from '../../../../../../EditPipelinePage.hooks'
import {
  getDraftJobs,
  isSuggestionSkipped,
  getSkippedSuggestions,
} from '../../../../../../EditPipelinePage.selectors'
import {pipelineDraft, suggestions} from '../../../../../../slices/EditPipelinePage.slices'
import type {SmartDetectorProps} from '../SmartDetectors.types'

import {parseMavenCommand} from './CliToMaven.utils'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

function CliToMaven({value, stepIndex, focused}: SmartDetectorProps) {
  const jobId = useJobId()!
  const id = usePipelineId()
  const stepId = `step-${jobId}-${stepIndex + 1}`
  const stepList = useAppSelector(state => getDraftJobs(state, id)?.[jobId]?.steps)
  const skippedSuggestionList = useAppSelector(state => getSkippedSuggestions(state, stepId))
  const isSkipped = useAppSelector(state =>
    isSuggestionSkipped(state, stepId, SuggestionType.CLI_TO_MAVEN),
  )

  const dispatch = useAppDispatch()

  const match = parseMavenCommand(value)
  const [_, goals] = match ?? []

  const visible = !isSkipped && !!match && focused

  return (
    <SuggestionMessage
      message={
        'Interested in automatic collection and display of test-results or parallel test runs?'
      }
      actionText="Convert to Maven build step"
      cancelText={'Ignore'}
      visible={visible}
      onCancelClick={() => {
        dispatch(
          suggestions.actions.skip({
            id: stepId,
            values: produce(skippedSuggestionList ?? [], draft => {
              if (!draft.includes(SuggestionType.CLI_TO_MAVEN)) {
                draft.push(SuggestionType.CLI_TO_MAVEN)
              }
            }),
          }),
        )
      }}
      onActionClick={() => {
        dispatch(
          suggestions.actions.showSuccessMessage({id: stepId, type: SuggestionType.CLI_TO_MAVEN}),
        )
        dispatch(
          pipelineDraft.actions.setSteps({
            id,
            jobId,
            steps: produce(stepList ?? [], draft => {
              draft[stepIndex] = {
                type: StepTypes.MAVEN,
                goals,
              }
            }),
          }),
        )
      }}
    />
  )
}

export default memo(CliToMaven)
