import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import {useCallback, useEffect, useRef} from 'react'
import type {RichTextareaHandle} from 'rich-textarea'

const classNameSuggestListItem = 'ring-list-item'

const waintTimeEndSliderAnimation = 600

function useHighlighterTextField(autoFocus: boolean, onBlur?: () => void) {
  const richTextareaRef = useRef<RichTextareaHandle | null>(null)
  const selectHighlighterTextFieldTokenHandler = (content: string) => (item: SelectItem) => {
    if (richTextareaRef.current != null) {
      const contentLength = content.length
      const {selectionStart = 0, selectionEnd = 0} = richTextareaRef.current
      const itemLabel = `%${item.key}%`
      const startInsertPosition = selectionStart - contentLength

      richTextareaRef.current.setRangeText(itemLabel, startInsertPosition, selectionEnd)
      richTextareaRef.current.selectionStart = startInsertPosition + itemLabel.length
      richTextareaRef.current.focus()
    }
  }
  const editableTextFieldBlurHandler = useCallback(
    (event: React.FocusEvent<HTMLTextAreaElement>) => {
      if (!event.relatedTarget?.classList?.contains(classNameSuggestListItem)) {
        onBlur?.()
      }
    },
    [onBlur],
  )

  useEffect(() => {
    if (autoFocus) {
      setTimeout(() => {
        richTextareaRef.current?.focus()
      }, waintTimeEndSliderAnimation)
    }
  }, [autoFocus])

  return {
    richTextareaRef,
    editableTextFieldBlurHandler,
    selectHighlighterTextFieldTokenHandler,
  }
}

export default useHighlighterTextField
