import {produce} from 'immer'

import {useEffect, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../../../../../hooks/react-redux'
import SuggestionMessage from '../../../../../../../components/SuggestionMessage/SuggestionMessage'
import {usePipelineId} from '../../../../../../../hooks/pipeline'
import {SuggestionType} from '../../../../../../../types'
import {useJobId} from '../../../../../../EditPipelinePage.hooks'
import {
  getDraftJobs,
  isSuggestionSkipped,
  getSkippedSuggestions,
} from '../../../../../../EditPipelinePage.selectors'
import {pipelineDraft, suggestions} from '../../../../../../slices/EditPipelinePage.slices'
import {WORKING_DIRECTORY} from '../../../../JobStepSidebar/JobStepSidebar.consts'
import type {SmartDetectorProps} from '../SmartDetectors.types'

function CdToWorkingDir({name, value, stepIndex, focused, anchorElement}: SmartDetectorProps) {
  const jobId = useJobId()!
  const id = usePipelineId()
  const stepId = `step-${jobId}-${stepIndex + 1}`
  const stepList = useAppSelector(state => getDraftJobs(state, id)?.[jobId]?.steps)
  const skippedSuggestionList = useAppSelector(state => getSkippedSuggestions(state, stepId))
  const isSkipped = useAppSelector(state =>
    isSuggestionSkipped(state, stepId, SuggestionType.CLI_TO_WORKING_DIR),
  )

  const currentStep = stepList?.[stepIndex]
  const dispatch = useAppDispatch()

  const match = value.match(/^cd ([\w\/]+)(?: && (.*)|\n([\s\S]*))$/)
  const [_, directory, inlineScript, script] = match ?? []
  const visible = !currentStep?.[WORKING_DIRECTORY] && !isSkipped && !!match && focused

  const [workingDirectory, setWorkingDirectory] = useState('')
  useEffect(() => {
    setWorkingDirectory(prevState => directory ?? prevState)
  }, [directory])

  return (
    <SuggestionMessage
      message={`We detected cd command. Set ${workingDirectory} as the working directory for this script instead? This will help us optimize your pipeline`}
      actionText="Set"
      visible={visible}
      onCancelClick={() => {
        dispatch(
          suggestions.actions.skip({
            id: stepId,
            values: produce(skippedSuggestionList ?? [], draft => {
              if (!draft.includes(SuggestionType.CLI_TO_WORKING_DIR)) {
                draft.push(SuggestionType.CLI_TO_WORKING_DIR)
              }
            }),
          }),
        )
      }}
      onActionClick={() => {
        dispatch(
          suggestions.actions.showSuccessMessage({
            id: stepId,
            type: SuggestionType.CLI_TO_WORKING_DIR,
          }),
        )
        dispatch(
          pipelineDraft.actions.setSteps({
            id,
            jobId,
            steps: produce(stepList ?? [], draft => {
              const step = draft[stepIndex]
              step[WORKING_DIRECTORY] = directory
              step[name] = inlineScript || script
            }),
          }),
        )
        anchorElement?.focus()
      }}
    />
  )
}

export default CdToWorkingDir
