import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'

import styles from './SummaryDetailsCardWrapper.module.css'

type SummaryDetailsCardWrapperProps = {
  children: React.ReactNode
  header?: React.ReactNode
  actions?: React.ReactNode
  error?: React.ReactNode
  showMoreButton?: boolean
  onClickShowMore?: () => void
  expanded?: boolean
  className?: string
}

function SummaryDetailsCardWrapper({
  children,
  header,
  actions,
  error,
  expanded,
  className,
  showMoreButton,
  onClickShowMore,
}: SummaryDetailsCardWrapperProps) {
  const actionsClassNames = classNames(styles.actions, {
    [styles.withHeader]: header,
  })
  const showMoreButtonTitle = expanded ? 'Show less' : 'Show more'

  return (
    <div className={classNames(styles.main, className)}>
      <div className={actionsClassNames}>{actions}</div>
      {header}
      {children}
      {error && <div className={styles.error}>{error}</div>}
      {showMoreButton && (
        <Button
          inline
          onClick={onClickShowMore}
          className={styles.showMoreButton}
          title={showMoreButtonTitle}
          aria-label={showMoreButtonTitle}
        >
          {showMoreButtonTitle}
        </Button>
      )}
    </div>
  )
}

export default SummaryDetailsCardWrapper
