import type {ReactNode} from 'react'

import SettingsBlock from '../SettingsBlock/SettingsBlock'

import PipelineParametersSettingsBlockDetails from './PipelineParametersSettingsBlockDetails'
import PipelineParametersSettingsBlockSummaryDetails from './PipelineParametersSettingsBlockSummaryDetails'
import usePipelineParametersSettingsBlock from './usePipelineParametersSettingsBlock'

type PipelineParametersProps = {
  blockId: string
  collapsible: boolean
  title: string
  collapsedNote?: string
  onEdit?: () => void
  error?: ReactNode
  parameters: Record<string, string | undefined>
  deleted?: string[]
}

function PipelineParametersSettingsBlock({
  title,
  blockId,
  collapsible,
  parameters = {},
  collapsedNote,
  error,
  onEdit,
  deleted,
}: PipelineParametersProps) {
  const {
    listItemLimit,
    isBlockExpanded,
    parametersKeys,
    isShowMoreButton,
    clickShowMoreButtonHandler,
  } = usePipelineParametersSettingsBlock(parameters)

  return (
    <SettingsBlock
      id={blockId}
      collapsible={collapsible}
      title={title}
      details={<PipelineParametersSettingsBlockDetails />}
      collapsedNote={collapsedNote}
      onAddClick={!collapsible ? onEdit : undefined}
    >
      <PipelineParametersSettingsBlockSummaryDetails
        parameters={parameters}
        parametersKeys={parametersKeys}
        deleted={deleted}
        error={error}
        isBlockExpanded={isBlockExpanded}
        isShowMoreButton={isShowMoreButton}
        onEdit={onEdit}
        onClickShowMore={clickShowMoreButtonHandler}
        listItemLimit={listItemLimit}
      />
    </SettingsBlock>
  )
}

export default PipelineParametersSettingsBlock
