import Code from '@jetbrains/ring-ui-built/components/code/code'
import {Fragment} from 'react'

import styles from './JobOutputParametersInfo.module.css'

function JobOutputParametersInfo() {
  return (
    <Fragment>
      {'To set a parameter value from inside a running step, print the following message:'}
      <Code className={styles.code} softWrap code='##teamcity[setParameter name="…" value="…"]' />
      <Code
        className={styles.code}
        softWrap
        code={`echo "##teamcity[setParameter name='myParam' value='newValue']"`}
      />
      {'To reference an output parameter in a downstream job, access it via the following syntax:'}
      <Code className={styles.code} softWrap code={`%job.<JobID>.<parameterName>%`} />
    </Fragment>
  )
}

export default JobOutputParametersInfo
