import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import type {ReactNode, MouseEvent} from 'react'
import {Suspense, useCallback, useState} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import Popup from '../../../../common/Popup/Popup'
import {useIsDebugRunning} from '../../EditPipelinePage/EditPipelinePage.hooks'
import {collapsedBlocks} from '../../EditPipelinePage/slices/EditPipelinePage.slices'
import useUID from '../../hooks/useUID'

import SettingsBlockHeader from './SettingsBlockHeader/SettingsBlockHeader'

import styles from './SettingsBlock.module.css'

const tooltipDirections = [Directions.LEFT_BOTTOM]

type Props = {
  id: string
  title: string | null | undefined
  generatedTitle?: string | null | undefined
  children?: ReactNode
  collapsible?: boolean
  collapsedDefault?: boolean
  collapsedNote?: ReactNode
  isDeleted?: boolean
  childrenVisible?: boolean
  details?: ReactNode
  disabled?: boolean
  rightElement?: ReactNode | ((editing: boolean) => ReactNode)
  onChangeName?: (name: string) => void
  onDeleteClick?: () => void
  onRestoreClick?: () => void
  onAddClick?: () => void
  updated?: boolean
  customActions?: (anchor: ReactNode) => ReactNode
  secondLine?: ReactNode
  draggable?: boolean
  collapsibleClassName?: string
}

function SettingsBlock({
  id,
  collapsedDefault,
  title,
  collapsible,
  children,
  generatedTitle,
  isDeleted,
  childrenVisible = false,
  draggable,
  collapsibleClassName,
  ...props
}: Props) {
  const isReadonly = useIsDebugRunning()
  const collapsed = useAppSelector(state => state.pipelines.collapsedBlocks[id] ?? collapsedDefault)
  const dispatch = useAppDispatch()
  const actuallyCollapsed = isDeleted || collapsed || (isReadonly && !childrenVisible)
  const regionId = useUID(`step-${title || generatedTitle}`)
  const buttonId = useUID(`button-${title}`)
  const toggleCollapseHandler = (state: boolean) => () =>
    dispatch(collapsedBlocks.actions.toggle({id, collapsed: state}))

  const [tooltipVisible, setTooltipVisible] = useState(false)
  const [tooltipCoordinates, setTooltipCoordinates] = useState([0, 0])
  const onBlockClick = useCallback(
    ({clientX, clientY, currentTarget}: MouseEvent<HTMLElement>) => {
      if (isReadonly) {
        const {left, top} = currentTarget.getBoundingClientRect()
        setTooltipCoordinates([clientX - left, clientY - top])
        setTooltipVisible(true)
      }
    },
    [isReadonly],
  )
  const onOutsideClick = useCallback(() => {
    setTooltipVisible(false)
  }, [])

  return (
    <div className={styles.section} role={'presentation'} onClick={onBlockClick}>
      <SettingsBlockHeader
        id={id}
        title={title}
        generatedTitle={generatedTitle}
        collapsed={actuallyCollapsed}
        isDeleted={isDeleted}
        isReadonly={isReadonly && !childrenVisible}
        collapse={toggleCollapseHandler(true)}
        collapsible={collapsible}
        buttonId={buttonId}
        expand={toggleCollapseHandler(false)}
        regionId={regionId}
        draggable={draggable}
        {...props}
      />
      {collapsible && (
        <div
          role="region"
          id={regionId}
          hidden={actuallyCollapsed}
          aria-labelledby={buttonId}
          className={classNames(styles.collapsibleRegion, collapsibleClassName)}
        >
          {!actuallyCollapsed && (
            <Suspense
              fallback={
                <span>
                  <LoaderInline>{'Loading...'}</LoaderInline>
                </span>
              }
            >
              {children}
            </Suspense>
          )}
        </div>
      )}
      {isReadonly && (
        <Popup
          className={styles.tooltip}
          hidden={!tooltipVisible}
          directions={tooltipDirections}
          left={tooltipCoordinates[0]}
          top={tooltipCoordinates[1]}
          onOutsideClick={onOutsideClick}
        >
          {
            'Job settings cannot be edited during a debug run. Stop the debug session or wait for it to finish'
          }
        </Popup>
      )}
    </div>
  )
}

export default SettingsBlock
