import {createContext, useContext, useMemo} from 'react'

import type {JobStepFormContextProps, JobStepFormProviderProps} from './JobStepFormContext.types'
import useJobStepFormProvider from './useJobStepFormProvider'

const JobStepFormContext = createContext<JobStepFormContextProps>({} as JobStepFormContextProps)

export const useJobStepFormContext = () => useContext(JobStepFormContext)

function JobStepFormProvider({children, value}: JobStepFormProviderProps) {
  const {getIsDetectorShow} = useJobStepFormProvider()
  const contextValue = useMemo(() => ({...value, getIsDetectorShow}), [value, getIsDetectorShow])

  return <JobStepFormContext.Provider value={contextValue}>{children}</JobStepFormContext.Provider>
}

export default JobStepFormProvider
