import isEmpty from 'lodash/isEmpty'
import {useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {emptyArray, getEmptyHash} from '../../../../../../../utils/empty'
import {extractFilePaths} from '../../../../../../../utils/fileUtils'
import {usePipelineId} from '../../../../hooks/pipeline'
import type {JobFile} from '../../../../types'
import {useJobId, usePipelineDraftExistingJob} from '../../../EditPipelinePage.hooks'

import {
  getDraftJobs,
  getPipeline,
} from 'src/components/pages/PipelinesPages/EditPipelinePage/EditPipelinePage.selectors'
import {pipelineDraft} from 'src/components/pages/PipelinesPages/EditPipelinePage/slices/EditPipelinePage.slices'
import {useAppDispatch, useAppSelector, useAppStore} from 'src/hooks/react-redux'

function useJobFilesPublicationStore() {
  const jobId = useJobId()!
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()
  const rawFilesPublication =
    usePipelineDraftExistingJob(jobId)?.['files-publication'] ?? emptyArray

  const filesPublication = useMemo(
    () =>
      rawFilesPublication.map(file => {
        if (typeof file === 'object') {
          const shareWithJobs = file['share-with-jobs']
          const publishArtifact = file['publish-artifact']

          if (!shareWithJobs && !publishArtifact) {
            return {
              ...file,
              'share-with-jobs': true,
            }
          }
        } else if (typeof file === 'string') {
          return {
            path: file,
            'share-with-jobs': true,
            'publish-artifact': false,
          }
        }
        return file
      }),
    [rawFilesPublication],
  )

  const addFilesPublicationHandler = useCallback(() => {
    dispatch(pipelineDraft.actions.addFilesPublication({pipelineId, jobId}))
  }, [dispatch, jobId, pipelineId])
  const deletedFilesPublication = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.filesPublication,
    shallowEqual,
  )
  const getIsKeyDelete = useCallback(
    (index: number) => deletedFilesPublication?.includes(`${jobId}_${index}`),
    [deletedFilesPublication, jobId],
  )
  const summaryNote = useMemo(
    () => filesPublication.filter((_, index) => !getIsKeyDelete(index)),
    [filesPublication, getIsKeyDelete],
  ).join('\n')
  const addedFilesPublication = useAppSelector(
    state => getPipeline(state, pipelineId)?.added?.filesPublication,
  )
  const clearAddedFilesPublicationHandler = useCallback(() => {
    dispatch(pipelineDraft.actions.clearFilesPublication({pipelineId, jobId}))
  }, [dispatch, jobId, pipelineId])
  const filesPublicationMultiplyConfirmHandler = useCallback(
    () => dispatch(pipelineDraft.actions.applyAddedFilesPublication(pipelineId)),
    [dispatch, pipelineId],
  )
  const filesPublicationMultiplyDeleteHandler = () => {
    const emptyFilePublicationIndex = filesPublication.reduce((acc, file, index) => {
      if (isEmpty(file.path)) {
        acc.push(index)
      }
      return acc
    }, [])

    dispatch(
      pipelineDraft.actions.multiplyDeleteFilesPublication({
        pipelineId,
        jobId,
        indexes: emptyFilePublicationIndex,
      }),
    )
  }
  const deleteFilesPublicationHandler = (index: number) => {
    dispatch(pipelineDraft.actions.deleteFilesPublication({pipelineId, jobId, index}))
  }
  const restoreFilesPublicationHandler = (index: number) => {
    dispatch(pipelineDraft.actions.restoreFilesPublication({pipelineId, jobId, index}))
  }
  const changeFilePublicationHandler = (index: number, file: JobFile) => {
    let updatedFile = file
    if (typeof file === 'object') {
      const shareWithJobs = file['share-with-jobs']
      const publishArtifact = file['publish-artifact']

      if (!shareWithJobs && !publishArtifact) {
        updatedFile = {
          ...file,
          'share-with-jobs': true,
        }
      }
    } else if (typeof file === 'string') {
      updatedFile = {
        path: file,
        'share-with-jobs': true,
        'publish-artifact': false,
      }
    }

    dispatch(
      pipelineDraft.actions.setFilesPublication({
        pipelineId,
        jobId,
        index,
        file: updatedFile,
      }),
    )
  }
  const {getState} = useAppStore()
  // Task: TCP-22 Rework "Use files..." link on Dependencies block
  // Update all dependencies jobs that have files dependencies
  const updateFilesDependenciesHandler = useCallback(() => {
    const files = extractFilePaths(filesPublication.filter(Boolean))
    const pipelineJobs = getDraftJobs(getState(), pipelineId) ?? getEmptyHash()
    for (const key in pipelineJobs) {
      if (key in pipelineJobs) {
        const job = pipelineJobs[key]
        job?.dependencies?.forEach(dependency => {
          const hasDependencyFiles =
            typeof dependency === 'object' && dependency?.[jobId]?.files?.length

          if (hasDependencyFiles) {
            dispatch(
              pipelineDraft.actions.setFilesDependencies({
                id: pipelineId,
                jobId: key,
                dependencyId: jobId,
                files,
              }),
            )
          }
        })
      }
    }
  }, [dispatch, filesPublication, getState, jobId, pipelineId])

  return {
    summaryNote,
    getIsKeyDelete,
    filesPublication,
    addedFilesPublication,
    deletedFilesPublication,
    addFilesPublicationHandler,
    changeFilePublicationHandler,
    deleteFilesPublicationHandler,
    restoreFilesPublicationHandler,
    updateFilesDependenciesHandler,
    clearAddedFilesPublicationHandler,
    filesPublicationMultiplyDeleteHandler,
    filesPublicationMultiplyConfirmHandler,
  }
}

export default useJobFilesPublicationStore
