import type {ReactNode} from 'react'

import PipelineParameter from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineParameters/PipelineParameter/PipelineParameter'
import styles from '../../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineParameters/PipelineParameters.module.css'
import EditButton from '../EditButton/EditButton'
import SummaryDetailsCardWrapper from '../SummaryDetailsCardWrapper/SummaryDetailsCardWrapper'

type PipelineParametersSettingsBlockSummaryDetailsProps = {
  parameters: Record<string, string | undefined>
  parametersKeys: string[]
  deleted?: string[]
  error?: ReactNode
  header?: ReactNode
  isBlockExpanded: boolean
  isShowMoreButton: boolean
  onEdit?: () => void
  onClickShowMore: () => void
  listItemLimit: number
}

function PipelineParametersSettingsBlockSummaryDetails({
  parameters,
  parametersKeys,
  deleted,
  header,
  error,
  isBlockExpanded,
  isShowMoreButton,
  listItemLimit,
  onEdit,
  onClickShowMore,
}: PipelineParametersSettingsBlockSummaryDetailsProps) {
  return (
    <SummaryDetailsCardWrapper
      actions={<EditButton title="Edit parameters" aria-label="Edit parameters" onClick={onEdit} />}
      error={error}
      header={header}
      expanded={isBlockExpanded}
      showMoreButton={isShowMoreButton}
      onClickShowMore={onClickShowMore}
    >
      <div className={styles.parametersHeader}>
        <div className={styles.parametersHeaderItem}>{'Name'}</div>
        <div className={styles.parametersHeaderItem}>{'Value'}</div>
      </div>
      {parametersKeys.slice(0, listItemLimit).map(key => {
        const value = parameters[key]
        const isDeleted = deleted?.includes(key)

        return <PipelineParameter key={key} value={value} name={key} deleted={isDeleted} />
      })}
    </SummaryDetailsCardWrapper>
  )
}

export default PipelineParametersSettingsBlockSummaryDetails
