import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import React from 'react'

import Icon from '../../../../../../../common/Icon/Icon'
import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import Input, {Size} from '../../../../../components/Input'
import PasswordInput from '../../../../../components/PasswordInput/PasswordInput'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {pipelineDraft} from '../../../../slices/EditPipelinePage.slices'
import {linkCloudImageHardwareDoc} from '../../../JobSettingsSidebar/JobAgentRequirements/JobAgentRequirements.consts'

import {passwordPlaceholder} from './DockerIntegrationForm.consts'

import styles from './DockerIntegrationForm.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import {useAppDispatch} from 'src/hooks/react-redux'
import {restApi} from 'src/services/rest'

type Props = {
  id?: string
  parameters: Record<string, string | null>
  isAdd?: boolean
  onClose: () => void
}

function DockerIntegrationForm({id, parameters, onClose, isAdd}: Props) {
  const pipelineId = usePipelineId()

  const userName = parameters.userName ?? ''
  const url = parameters.repositoryUrl ?? ''
  const password = parameters['secure:userPass'] ?? passwordPlaceholder // null means saved password

  const editSettingsFormTitle = `${isAdd ? 'Add' : 'Edit'} Docker Integration`
  const dispatch = useAppDispatch()
  const setParameters = (newParameters: Record<string, string>) =>
    dispatch(
      pipelineDraft.actions.editIntegration({
        pipelineId,
        id,
        parameters: newParameters,
      }),
    )

  const [testDockerConnection, {testResult, isTesting, reset}] =
    restApi.endpoints.testDockerConnection.useMutation({
      selectFromResult: ({data, isLoading}) => ({
        testResult: data,
        isTesting: isLoading,
      }),
    })
  const errors = [...(testResult?.querySelectorAll('error') ?? [])]
  const inputUserNameChangeHandler = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
    setParameters({userName: currentTarget.value})
    reset()
  }
  const inputPasswordChangeHandler = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
    setParameters({'secure:userPass': currentTarget.value})
    reset()
  }
  const isButtonTestConnectionDisabled = !userName || !password

  const deleteHandler = () => {
    dispatch(
      pipelineDraft.actions.deleteIntegration({
        id: id!,
        name: parameters!.displayName!,
        pipelineId,
      }),
    )

    onClose()
  }

  return (
    <EditSettingsForm
      settingsClassName={styles.dockerIntegrationForm}
      onConfirmClick={onClose}
      onDeleteClick={deleteHandler}
      title={editSettingsFormTitle}
      actions={
        !isButtonTestConnectionDisabled && (
          <Button
            className={styles.testDockerConnection}
            onClick={() => testDockerConnection({url, userName, userPass: password})}
            loader={isTesting}
            disabled={isButtonTestConnectionDisabled}
            inline
          >
            {'Test Connection'}
          </Button>
        )
      }
    >
      <Input
        label={'URL'}
        type="url"
        spellCheck={false}
        size={Size.FULL}
        value={url}
        onChange={e => setParameters({repositoryUrl: e.currentTarget.value})}
        autoFocus
      />
      <Input
        size={Size.FULL}
        label={'Username'}
        value={userName}
        onChange={inputUserNameChangeHandler}
      />
      <PasswordInput
        label={
          <React.Fragment>
            {'Password'}
            <HelpDetails>
              {
                'Leave this field empty to access public images in the anonymous mode. Note that Dockerhub imposes '
              }
              <Link target="_blank" href={linkCloudImageHardwareDoc} rel="noreferrer">
                {'rate limits'}
              </Link>
              {' for anonymous users.'}
            </HelpDetails>
          </React.Fragment>
        }
        size={Size.FULL}
        placeholder={'Leave empty for anonymous'}
        value={password}
        onChange={inputPasswordChangeHandler}
        showEyeButton={password != null && password.length > 0 && password !== passwordPlaceholder}
      />
      {isTesting && (
        <div className={styles.loaderInline}>
          <Icon name="running" />
          {'Test connection in process'}
        </div>
      )}
      {testResult != null && (
        <div className={styles.testDockerConnectionBlock}>
          {errors.length > 0 ? (
            errors.map(error => (
              <span key={error.textContent} className={styles.error}>
                {error.textContent}
              </span>
            ))
          ) : (
            <span className={styles.success}>{'Test connection succeeded'}</span>
          )}
        </div>
      )}
    </EditSettingsForm>
  )
}

export default DockerIntegrationForm
