import {useMemo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import type {PipelineId} from '../../../../../../types'
import {deduplicate} from '../../../../../../utils/array'
import {getJobName, makePipelineErrorsSelector} from '../../EditPipelinePage.selectors'

function useSaveChangesError(pipelineId: PipelineId) {
  const selector = useMemo(() => makePipelineErrorsSelector(), [])
  const pipelineErrors = useAppSelector(state => selector(state, {pipelineId}))

  const pipelineSettingsErrors = useMemo(
    () => deduplicate(pipelineErrors.filter(({jobId}) => jobId == null)),
    [pipelineErrors],
  )
  const errorJobIds = useMemo(
    () => deduplicate(pipelineErrors.map(({jobId}) => jobId)),
    [pipelineErrors],
  )
  const errorJobsString = useAppSelector(state =>
    errorJobIds
      .map(jobId => (jobId != null ? getJobName(state, pipelineId, jobId) : 'pipeline'))
      .join(', '),
  )
  const hasErrors = Boolean(pipelineErrors.length)
  const hasSettingsErrors = Boolean(pipelineSettingsErrors.length)
  const errorJobsLabel = useMemo(() => {
    const prefixErrorMessage =
      pipelineErrors.length === 1 ? pipelineErrors[0].message : 'Invalid settings'

    return errorJobsString ? `${prefixErrorMessage} in ${errorJobsString}` : ''
  }, [errorJobsString, pipelineErrors])

  return {
    hasErrors,
    hasSettingsErrors,
    errorJobsLabel,
  }
}

export default useSaveChangesError
