import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import {memo, useRef} from 'react'
import {Transition} from 'react-transition-group'

import Icon from '../../../../common/Icon/Icon'

import styles from './SuggestionMessage.module.css'

type Props = {
  message: string
  actionText: string
  cancelText?: string
  visible?: boolean
  reduceAnimation?: boolean
  icon?: string
  containerClassName?: string
  onActionClick: () => void
  onCancelClick?: () => void
  onMouseEnter?: () => void
  onMouseLeave?: () => void
}

function SuggestionMessage({
  message,
  actionText,
  cancelText = 'Skip it',
  visible,
  reduceAnimation,
  icon = 'sparkles',
  containerClassName,
  onActionClick,
  onCancelClick,
  onMouseEnter,
  onMouseLeave,
}: Props) {
  const nodeRef = useRef(null)

  return (
    <Transition
      appear={process.env.NODE_ENV !== 'test'}
      unmountOnExit
      nodeRef={nodeRef}
      in={visible}
      timeout={300}
    >
      {state => {
        const animationClassName = `${styles[state]}`
        const containerAnimationClassNames = classNames(
          styles.container,
          containerClassName,
          animationClassName,
          {
            [styles.reduceAnimation]: reduceAnimation,
          },
        )

        return (
          <div
            className={containerAnimationClassNames}
            ref={nodeRef}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
          >
            <Icon name={`${icon}-36px`} className={styles.icon} />
            <div>
              <div className={styles.message}>{message}</div>
              <Button inline className={styles.mainAction} onClick={onActionClick}>
                {actionText}
              </Button>
              <Button inline className={styles.secondaryAction} onClick={onCancelClick}>
                {cancelText}
              </Button>
            </div>
          </div>
        )
      }}
    </Transition>
  )
}

export default memo(SuggestionMessage)
