import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'

import Icon from '../../../../../../../common/Icon/Icon'
import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import Input, {Size} from '../../../../../components/Input'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {isTestNpmConnectionEnabled} from '../../../../../utils/featureToggles'
import {pipelineDraft} from '../../../../slices/EditPipelinePage.slices'

import {npmDetailsLink, tokenPlaceholder} from './NpmIntegrationForm.consts'

import styles from './NpmIntegrationForm.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import {useAppDispatch} from 'src/hooks/react-redux'
import {restApi} from 'src/services/rest'

type Props = {
  id?: string
  parameters: Record<string, string | null>
  isAdd?: boolean
  onClose: () => void
}

function NpmIntegrationForm({onClose, id, parameters, isAdd}: Props) {
  const pipelineId = usePipelineId()

  const url = parameters.npmRegistryHost ?? ''
  const scope = parameters.npmRegistryScope ?? ''
  const token = parameters['secure:npmRegistryToken'] ?? tokenPlaceholder // null means saved token

  const editSettingsFormTitle = `${isAdd ? 'Add' : 'Edit'} NPM Integration`
  const dispatch = useAppDispatch()
  const setParameters = (newParameters: Record<string, string>) =>
    dispatch(
      pipelineDraft.actions.editIntegration({
        pipelineId,
        id,
        parameters: newParameters,
      }),
    )

  const [testNpmConnection, {testResult, isTesting, reset}] =
    restApi.endpoints.testNpmConnection.useMutation({
      selectFromResult: ({data, isLoading}) => ({
        testResult: data,
        isTesting: isLoading,
      }),
    })
  const inputScopeChangeHandler = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
    setParameters({npmRegistryScope: currentTarget.value})
    if (isTestNpmConnectionEnabled) {
      reset()
    }
  }
  const inputAccessTokenChange = ({currentTarget}: React.ChangeEvent<HTMLInputElement>) => {
    setParameters({'secure:npmRegistryToken': currentTarget.value})
    if (isTestNpmConnectionEnabled) {
      reset()
    }
  }
  const errors = [...(testResult?.querySelectorAll('error') ?? [])]
  const isButtonTestConnectionDisabled = !scope || !token || !isTestNpmConnectionEnabled

  const deleteHandler = () => {
    dispatch(
      pipelineDraft.actions.deleteIntegration({
        id: id!,
        name: parameters!.displayName!,
        pipelineId,
      }),
    )

    onClose()
  }

  return (
    <EditSettingsForm
      settingsClassName={styles.npmIntegrationForm}
      onConfirmClick={onClose}
      onDeleteClick={deleteHandler}
      title={editSettingsFormTitle}
      actions={
        !isButtonTestConnectionDisabled && (
          <Button
            className={styles.testNpmConnection}
            disabled={isButtonTestConnectionDisabled}
            onClick={() => testNpmConnection({url, scope, token})}
            loader={isTesting}
            inline
          >
            {'Test Connection'}
          </Button>
        )
      }
    >
      <Input
        label={'URL'}
        type="url"
        spellCheck={false}
        size={Size.FULL}
        value={url}
        onChange={e => setParameters({npmRegistryHost: e.currentTarget.value})}
        autoFocus
      />
      <Input
        size={Size.FULL}
        aria-label={'Scope'}
        label={
          <>
            {'Scope'}
            <HelpDetails>
              {
                'Specify a scope for multiple registries. Leave empty to use this registry as default for all npm/yarn commands. '
              }
              <Link target="_blank" rel="noreferrer" href={npmDetailsLink}>
                {'Details'}
              </Link>
            </HelpDetails>
          </>
        }
        value={scope}
        onChange={inputScopeChangeHandler}
      />
      <Input
        label={'Access Token'}
        size={Size.FULL}
        data-imitate-password
        placeholder={'Leave empty for anonymous'}
        value={token}
        onChange={inputAccessTokenChange}
      />
      {isTestNpmConnectionEnabled && (
        <>
          {isTesting && (
            <div className={styles.loaderInline}>
              <Icon name="running" />
              {'Test connection in process'}
            </div>
          )}
          {testResult != null && (
            <div className={styles.testNpmConnectionBlock}>
              {errors.length > 0 ? (
                errors.map(error => (
                  <span key={error.textContent} className={styles.error}>
                    {error.textContent}
                  </span>
                ))
              ) : (
                <span className={styles.success}>{'Success'}</span>
              )}
            </div>
          )}
        </>
      )}
    </EditSettingsForm>
  )
}

export default NpmIntegrationForm
