import {produce} from 'immer'

import {memo, useCallback} from 'react'

import SuggestionMessage from '../../../../../../../components/SuggestionMessage/SuggestionMessage'
import {usePipelineId} from '../../../../../../../hooks/pipeline'
import {SuggestionType} from '../../../../../../../types'
import {useJobId} from '../../../../../../EditPipelinePage.hooks'
import {
  getDraftJobs,
  getSkippedSuggestions,
  isSuggestionSkipped,
} from '../../../../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  suggestions,
} from '../../../../../../slices/EditPipelinePage.slices'
import {useJobStepFormContext} from '../../JobStepFormContext/JobStepFormContext'
import type {SmartDetectorProps} from '../SmartDetectors.types'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

function Parallelism({stepIndex}: SmartDetectorProps) {
  const id = usePipelineId()
  const jobId = useJobId()!
  const stepId = `step-${jobId}-${stepIndex + 1}`
  const skippedSuggestionList = useAppSelector(state => getSkippedSuggestions(state, stepId))
  const isSkipped = useAppSelector(state =>
    isSuggestionSkipped(state, stepId, SuggestionType.PARALLELISM),
  )
  const parallelismCount = useAppSelector(
    state => getDraftJobs(state, id)?.[jobId]?.parallelism || 1,
  )
  const dispatch = useAppDispatch()
  const {getIsDetectorShow} = useJobStepFormContext()
  const isDetectorShow = getIsDetectorShow?.(jobId, SuggestionType.PARALLELISM, stepId)
  const visible = !isSkipped && parallelismCount < 2 && isDetectorShow
  const suggestionMessageCancelClickHandler = useCallback(() => {
    dispatch(
      suggestions.actions.skip({
        id: stepId,
        values: produce(skippedSuggestionList ?? [], draft => {
          if (!draft.includes(SuggestionType.PARALLELISM)) {
            draft.push(SuggestionType.PARALLELISM)
          }
        }),
      }),
    )
  }, [dispatch, skippedSuggestionList, stepId])
  const suggestionMessageActionClickHandler = useCallback(() => {
    const applyParallelismCountWaitTime = 10

    dispatch(collapsedBlocks.actions.toggle({id: 'optimizations', collapsed: false}))
    setTimeout(
      () =>
        dispatch(
          pipelineDraft.actions.setParallelismCount({
            id,
            jobId,
            value: 2,
          }),
        ),
      applyParallelismCountWaitTime,
    )
  }, [dispatch, id, jobId])

  if (!visible) {
    return null
  }

  return (
    <SuggestionMessage
      message={'Use Parallel Tests for a ~75% faster run time'}
      actionText="Set up parallel tests"
      icon={'broken-arrow'}
      visible={visible}
      reduceAnimation={visible}
      onCancelClick={suggestionMessageCancelClickHandler}
      onActionClick={suggestionMessageActionClickHandler}
    />
  )
}

export default memo(Parallelism)
