import type {NormalizeTokens} from '../Highlighter/Highlighter.types'

export function getCorretPositonIndexToken(tokens: NormalizeTokens[], corretPositonStart: number) {
  let tokensString = ''

  for (let i = 0; i < tokens.length; i++) {
    tokensString += tokens[i].line

    if (tokensString.length >= corretPositonStart) {
      return i
    }
  }

  return tokens.length - 1
}
