import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import type {ReactElement} from 'react'

import {isUnityRunnerEnabled} from '../../../../utils/featureToggles'
import {IntegrationType} from '../Integrations.consts'

import styles from './AddIntegration.module.css'

type Props = {
  onSelectIntegration: (type: IntegrationType) => void
  anchor: ReactElement
}

function AddIntegration({onSelectIntegration, anchor}: Props) {
  const unityLicenseIntegration = {
    label: 'Unity License',
    details: 'Specifies options for Unity license activation',
    onClick: () => onSelectIntegration(IntegrationType.UNITY),
  }

  return (
    <Dropdown className={styles.addIntegration} anchor={anchor}>
      <PopupMenu
        className={styles.popupMenu}
        data={[
          {
            label: 'NPM',
            details:
              'Allows Jobs to access a private npm registry during a build (example to download a package)',
            onClick: () => onSelectIntegration(IntegrationType.NPM),
          },
          {
            label: 'Docker Repository',
            details: "Securely runs 'Docker login' before your job",
            onClick: () => onSelectIntegration(IntegrationType.DOCKER),
          },
          ...(isUnityRunnerEnabled ? [unityLicenseIntegration] : []),
        ]}
        closeOnSelect
      />
    </Dropdown>
  )
}

export default AddIntegration
