import {ControlLabel} from '@jetbrains/ring-ui-built/components/control-label/control-label'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import classNames from 'classnames'
import {forwardRef} from 'react'
import type {ReactNode} from 'react'
import type React from 'react'
import {mergeRefs} from 'react-merge-refs'
import {RichTextarea, type RichTextareaProps} from 'rich-textarea'

import Highlighter from '../Highlighter/Highlighter'
import type {NormalizeTokens} from '../Highlighter/Highlighter.types'

import HighlighterTextFieldProvider from './HighlighterTextFieldContext'
import type {HighlighterTextFieldSpot} from './HighlighterTextFieldContext.types'
import HighlighterTextFieldToken from './HighlighterTextFieldToken'
import useHighlighterTextField from './useHighlighterTextField'
import {getCorretPositonIndexToken} from './useHighlighterTextField.utils'

import styles from './HighlighterTextField.module.css'

type HightlighterRichTextareaProps = {
  value?: string
  onChange: (value: React.ChangeEvent<HTMLTextAreaElement>) => void
  label?: ReactNode
  disabled?: boolean
  onBlur?: () => void
  onFocus?: () => void
  error?: React.ReactNode | null | undefined
  height?: ControlsHeight
  multiline?: boolean
  autoFocus?: boolean
  placeholder?: string
  spot?: HighlighterTextFieldSpot
} & Partial<RichTextareaProps>

const richTextareaStyles: React.CSSProperties = {
  width: '100%',
  display: 'inline-block',
  whiteSpace: 'pre-wrap',
  paddingBottom: '3px',
  overflow: 'initial',
}

const HighlighterTextField = forwardRef<HTMLTextAreaElement, HightlighterRichTextareaProps>(
  function HighlighterTextField(
    {
      value,
      label,
      placeholder,
      error,
      multiline,
      height = ControlsHeight.S,
      className,
      disabled,
      onBlur,
      onChange,
      onFocus,
      autoFocus = false,
      spot,
      ...props
    },
    ref,
  ) {
    const {richTextareaRef, editableTextFieldBlurHandler, selectHighlighterTextFieldTokenHandler} =
      useHighlighterTextField(autoFocus, onBlur)
    const contentEditableClassNames = classNames(className, 'ring-input-input')
    const outerContainerClassNames = classNames('ring-input-outerContainer', {
      [styles.heightS]: height === ControlsHeight.S,
      [styles.heightM]: height === ControlsHeight.M,
      ['ring-input-error']: error != null,
    })

    return (
      <HighlighterTextFieldProvider spot={spot}>
        <div className={styles.container}>
          <div className={outerContainerClassNames}>
            {label && <ControlLabel disabled={disabled}>{label}</ControlLabel>}
            <div className={'ring-input-container'}>
              <RichTextarea
                ref={mergeRefs([richTextareaRef, ref])}
                value={value ?? ''}
                className={contentEditableClassNames}
                placeholder={placeholder}
                disabled={disabled}
                rows={1}
                data-enable-grammarly="false"
                autoHeight={false}
                onBlur={editableTextFieldBlurHandler}
                onChange={onChange}
                onFocus={onFocus}
                style={richTextareaStyles}
                {...props}
              >
                {code => (
                  <Highlighter code={code} multiline={multiline}>
                    {({tokens}) =>
                      tokens.map(({line, type}: NormalizeTokens, index: number) => {
                        const elementKey = `element-${index}`
                        const selectionStart = richTextareaRef.current?.selectionStart ?? 0
                        const isIncludedLine =
                          type === 'typing' &&
                          getCorretPositonIndexToken(tokens, selectionStart) === index

                        return (
                          <HighlighterTextFieldToken
                            key={elementKey}
                            line={line}
                            type={type}
                            index={index}
                            isIncludedLine={isIncludedLine}
                            onSelect={selectHighlighterTextFieldTokenHandler(line)}
                          />
                        )
                      })
                    }
                  </Highlighter>
                )}
              </RichTextarea>
            </div>
            {error && (
              <div className={classNames('ring-input-errorText', styles.errorText)}>{error}</div>
            )}
          </div>
        </div>
      </HighlighterTextFieldProvider>
    )
  },
)

export default HighlighterTextField
