import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo, useCallback, useContext} from 'react'

import {copyClipboard} from '../../../../../../../../utils/clipboard'
import Actions from '../../../../../components/Actions/Actions'
import HighlighterTextView from '../../../../../components/HighlighterTextField/HighlighterTextView'
import {DisabledContext} from '../../../../../contexts/DisabledContext'
import useParametersControl from '../../../../../contexts/ParametersControl/useParametersControl'
import PipelineParameterForm from '../PipelineParameterForm/PipelineParameterForm'

import {
  emptyStateName,
  emptyStateValue,
  copyClipboardMessageTimeout,
} from './PipelineParameter.const'
import type {PipelineParameterProps} from './PipelineParameter.types'

import styles from './PipelineParameter.module.css'

function PipelineParameter({
  value = '',
  isEditMode,
  inputRef,
  name,
  deleted,
}: PipelineParameterProps) {
  const {currentParametersName, deleteParametersHandler, restoreParametersHandler} =
    useParametersControl(name)
  const clickCopyToClipboardButtonHandler = useCallback(
    (clipboardValue?: string) => async () => {
      try {
        if (clipboardValue) {
          await copyClipboard(clipboardValue)
          alert.message(`Parameter name copied to clipboard`, copyClipboardMessageTimeout)
        }
      } catch (error) {
        // eslint-disable-next-line no-console
        console.error(error)
      }
    },
    [],
  )
  const isDisabled = useContext(DisabledContext)
  const isNameEmpty = !currentParametersName
  const isValueEmpty = !value
  const parameterName = isNameEmpty ? emptyStateName : currentParametersName
  const valueState = isValueEmpty ? emptyStateValue : value

  if (isEditMode && !isDisabled && !deleted) {
    return (
      <div className={styles.parameter} data-test="job-parameter">
        <PipelineParameterForm
          inputRef={inputRef}
          onDelete={deleteParametersHandler}
          savedName={name}
        />
      </div>
    )
  }

  return (
    <div
      className={classNames(styles.parameter, styles.parameterPreview, {
        [styles.parameterPreviewEdit]: isEditMode,
      })}
      data-test="job-parameter"
    >
      <div className={classNames(styles.inputs, {[styles.deleted]: deleted})}>
        <div className={classNames(styles.parameterName, {[styles.emptyField]: isNameEmpty})}>
          <IconButton
            icon="copy"
            title="Copy to clipboard"
            aria-label="Copy to clipboard"
            className={styles.copyButton}
            onClick={clickCopyToClipboardButtonHandler(currentParametersName)}
          />
          {parameterName}
        </div>
        <div className={classNames(styles.parameterValue, {[styles.emptyField]: isValueEmpty})}>
          <HighlighterTextView value={valueState} multiline />
        </div>
      </div>
      <Actions
        className={styles.parameterActions}
        deleted={deleted}
        disabled={isDisabled}
        onRestoreClick={restoreParametersHandler}
        onDeleteClick={deleteParametersHandler}
      />
    </div>
  )
}

export default memo(PipelineParameter)
