import Toggle from '@jetbrains/ring-ui-built/components/toggle/toggle'
import classNames from 'classnames'
import {memo} from 'react'

import Actions from '../../../../components/Actions/Actions'
import {usePipelineId} from '../../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import {isPipelineFormAdd, isPipelineFormOpened} from '../../../EditPipelinePage.selectors'
import {pipelineDraft, pipelineForm} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'
import {integrations} from '../Integrations.consts'
import IntegrationSettingsForm from '../IntegrationSettingsForm/IntegrationSettingsForm'

import styles from './Integration.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  id: string
  jobId?: string
  type: string
  parameters: Record<string, string | null>
  isDeleted?: boolean
  isEnabled?: boolean
  unsaved?: boolean
}

function Integration({id, type, jobId, parameters, isDeleted, isEnabled = !isDeleted}: Props) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const pipelineId = usePipelineId()
  const formParams = {pipelineId, jobId, id, type: FormType.PIPELINE_INTEGRATION}
  const isEditing = useAppSelector(state => isPipelineFormOpened(state, formParams))
  const isAdd = useAppSelector(state => isPipelineFormAdd(state, formParams))
  const dispatch = useAppDispatch()

  const integration = integrations[type]
  const integrationClassNames = classNames(styles.integration, {
    [styles.disabled]: !isEnabled,
    [styles.deleted]: isDeleted,
  })

  if (integration == null) {
    return null
  }

  const content = (
    <div>
      <div className={styles.name}>{integration.displayName}</div>
      {integration.note && <div className={styles.note}>{integration.note(parameters)}</div>}
    </div>
  )

  return (
    <div className={integrationClassNames}>
      {!isEditing ? (
        <>
          {jobId != null ? (
            <Toggle
              className={styles.toggle}
              checked={isEnabled}
              disabled={isDeleted}
              onChange={e =>
                dispatch(
                  pipelineDraft.actions.toggleIntegration({
                    id: parameters.displayName!,
                    pipelineId,
                    jobId,
                    disabled: !e.currentTarget.checked,
                  }),
                )
              }
            >
              {content}
            </Toggle>
          ) : (
            content
          )}
          {canEditPipeline && (
            <Actions
              className={styles.actions}
              deleted={isDeleted}
              onEditClick={() => dispatch(pipelineForm.actions.open(formParams))}
              onDeleteClick={() =>
                dispatch(
                  pipelineDraft.actions.deleteIntegration({
                    id,
                    name: parameters.displayName!,
                    pipelineId,
                  }),
                )
              }
              onRestoreClick={() => {
                dispatch(
                  pipelineDraft.actions.restoreIntegration({
                    pipelineId,
                    id,
                  }),
                )
              }}
            />
          )}
        </>
      ) : (
        <IntegrationSettingsForm
          id={id}
          type={type}
          parameters={parameters}
          onClose={() => dispatch(pipelineForm.actions.close(formParams))}
          isAdd={isAdd}
        />
      )}
    </div>
  )
}

export default memo(Integration)
