import {createContext, memo} from 'react'

import type {
  ParametersControlContextProps,
  ParametersControlProviderProps,
} from './ParametersControlContext.types'

export const ParametersControlContext = createContext<ParametersControlContextProps>(
  {} as ParametersControlContextProps,
)

function ParametersControlProvider({children, value}: ParametersControlProviderProps) {
  return (
    <ParametersControlContext.Provider value={value}>{children}</ParametersControlContext.Provider>
  )
}

export default memo(ParametersControlProvider)
