import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import SelectPopup from '@jetbrains/ring-ui-built/components/select/select__popup'
import {Fragment, useMemo} from 'react'

import {runnersNameMap} from '../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobSteps/JobStep/JobStepJsonForm/JobStepJsonForm.const'
import RunnerIconButton from '../RunnerIconButton/RunnerIconButton'
import {getRunnerIconButton} from '../RunnerIconButton/RunnerIconButton.utils'

import useSelectRunner from './useSelectRunner'

import styles from './SelectRunner.module.css'

type SelectRunnerProps = {
  runners?: string[]
  selected?: string
  onSelect: (value: string) => void
  className?: string
}

function SelectRunner({runners, selected, onSelect, className}: SelectRunnerProps) {
  const {
    containerClassName,
    hasExtraRunners,
    setHiddenRunnerDropdown,
    alwaysFirstRunner,
    isHiddenRunnerDropdown,
    runnersToShow,
    sortedRunners,
    amountRunnersToShow,
  } = useSelectRunner(runners, selected, className)
  const extraRunners = useMemo(() => {
    const extraRunners = sortedRunners.slice(amountRunnersToShow)
    return extraRunners.map(key => {
      const LeftIcon = getRunnerIconButton(key.toLowerCase())

      return {
        label: (
          <div className={styles.extraRunnersMenuItem}>
            <div className={styles.extraRunnersMenuItemIcon}>
              <LeftIcon />
            </div>
            {key}
          </div>
        ),
        key,
      }
    })
  }, [amountRunnersToShow, sortedRunners])

  return (
    <div className={containerClassName}>
      <div className={styles.container}>
        <div className={styles.runner}>
          <RunnerIconButton
            selected={alwaysFirstRunner === selected}
            icon={alwaysFirstRunner?.toLowerCase()}
            onClick={onSelect}
            value={alwaysFirstRunner}
            label={alwaysFirstRunner}
            className={styles.runnerIconButton}
          />
        </div>
        {runnersToShow.map(runner => (
          <div key={runner} className={styles.runner}>
            <RunnerIconButton
              selected={runner.toLowerCase() === selected}
              icon={runner.toLowerCase()}
              onClick={onSelect}
              value={runner}
              label={runnersNameMap[runner]}
              className={styles.runnerIconButton}
            />
          </div>
        ))}
        {hasExtraRunners && (
          <div className={styles.runner}>
            <Dropdown
              anchor={
                <RunnerIconButton
                  onClick={() => setHiddenRunnerDropdown(!isHiddenRunnerDropdown)}
                  label="MORE"
                  className={styles.runnerIconButton}
                  icon="add"
                />
              }
            >
              <Fragment>
                {!isHiddenRunnerDropdown && (
                  <SelectPopup
                    hidden={isHiddenRunnerDropdown}
                    onCloseAttempt={() => setHiddenRunnerDropdown(true)}
                    onSelect={value => {
                      onSelect(value.key)
                      setHiddenRunnerDropdown(true)
                    }}
                    data={extraRunners}
                  />
                )}
              </Fragment>
            </Dropdown>
          </div>
        )}
      </div>
    </div>
  )
}
export default SelectRunner
