import {useAppSelector} from '../../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {matchError} from '../../../../../utils/validators'
import {FormType} from '../../../../slices/EditPipelinePage.slices.types'

function usePipelineParameterForm(savedName: string) {
  const pipelineId = usePipelineId()
  const isFormInvalid = useAppSelector(state =>
    state.pipelines.pipelineErrors.some(
      matchError({pipelineId, formType: FormType.PARAMETER, formId: savedName}),
    ),
  )

  return {
    isFormInvalid,
  }
}

export default usePipelineParameterForm
