import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import EditButton from '../EditButton/EditButton'

import styles from './Actions.module.css'

type Props = {
  className?: string
  iconClassName?: string
  onEditClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  editBtnTitle?: string
  onDeleteClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  deleteBtnTitle?: string
  onRestoreClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  restoreBtnTitle?: string
  onAddClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  addBtnTitle?: string
  disabled?: boolean
  deleted?: boolean
  hiddenDefault?: boolean
}

function Actions({
  className,
  iconClassName,
  deleted,
  disabled,
  onEditClick,
  onDeleteClick,
  onRestoreClick,
  onAddClick,
  hiddenDefault = true,
  addBtnTitle,
  editBtnTitle,
  deleteBtnTitle,
  restoreBtnTitle,
}: Props) {
  return (
    <div
      className={classNames(styles.actions, {[styles.hiddenDefault]: hiddenDefault}, className)}
      role="presentation"
      onClick={e => e.stopPropagation()}
    >
      {deleted ? (
        onRestoreClick && (
          <IconButton
            className={styles.actionButton}
            icon={'update'}
            title={restoreBtnTitle ?? 'Restore'}
            aria-label={restoreBtnTitle ?? 'Restore'}
            onClick={onRestoreClick}
            disabled={disabled}
          />
        )
      ) : (
        <>
          {onEditClick && (
            <EditButton
              className={styles.actionButton}
              title={editBtnTitle ?? 'Edit'}
              aria-label={editBtnTitle ?? 'Edit'}
              onClick={onEditClick}
              disabled={disabled}
            />
          )}
          {onDeleteClick && (
            <IconButton
              className={styles.actionButton}
              icon={'trash'}
              title={deleteBtnTitle ?? 'Delete'}
              aria-label={deleteBtnTitle ?? 'Delete'}
              onClick={onDeleteClick}
              disabled={disabled}
            />
          )}
          {onAddClick && (
            <IconButton
              className={classNames(styles.actionButton, styles.addButton)}
              iconClassName={iconClassName}
              icon={'add'}
              title={addBtnTitle ?? 'Add'}
              aria-label={addBtnTitle ?? 'Add'}
              onClick={onAddClick}
              disabled={disabled}
            />
          )}
        </>
      )}
    </div>
  )
}

export default React.memo(Actions)
