import chevronDownIcon from '@jetbrains/icons/chevron-down.svg'
import chevronRightIcon from '@jetbrains/icons/chevron-right.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {memo, useMemo, useCallback, useContext, useState} from 'react'
import * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {DisabledContext} from '../../../contexts/DisabledContext'
import {useJobId} from '../../../EditPipelinePage/EditPipelinePage.hooks'
import {isPipelineFormOpened} from '../../../EditPipelinePage/EditPipelinePage.selectors'
import {pipelineForm} from '../../../EditPipelinePage/slices/EditPipelinePage.slices'
import {FormType} from '../../../EditPipelinePage/slices/EditPipelinePage.slices.types'
import {usePipelineId} from '../../../hooks/pipeline'
import Actions from '../../Actions/Actions'
import EditSettingsForm from '../../EditSettingsForm/EditSettingsForm'

import styles from './SettingsBlockHeader.module.css'

import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'
import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

type Props = {
  id: string
  collapsed: boolean
  isDeleted?: boolean
  isReadonly?: boolean
  collapsible?: boolean
  collapsedNote?: ReactNode
  onChangeName?: (name: string) => void
  onDeleteClick?: () => void
  onRestoreClick?: () => void
  onAddClick?: () => void
  collapse: () => void
  expand: () => void
  regionId: string
  buttonId: string
  title: string | null | undefined
  generatedTitle: string | null | undefined
  details?: ReactNode
  rightElement?: ReactNode | ((editing: boolean) => ReactNode)
  updated?: boolean
  customActions?: (anchor: ReactNode) => ReactNode
  secondLine?: ReactNode
  draggable?: boolean
  disabled?: boolean
}

function SettingsBlockHeader({
  id,
  collapsed,
  isDeleted,
  isReadonly,
  collapsible,
  collapsedNote,
  onChangeName,
  onDeleteClick,
  onRestoreClick,
  onAddClick,
  collapse,
  expand,
  buttonId,
  regionId,
  title,
  generatedTitle,
  details,
  rightElement,
  customActions,
  secondLine,
  draggable,
  disabled,
}: Props) {
  const [isDetailsIconHover, setDetailsIconHover] = useState<boolean>(false)
  const pipelineId = usePipelineId()
  const jobId = useJobId()
  const formParams = useMemo(
    () => ({pipelineId, jobId, id, type: FormType.BLOCK_HEADER}),
    [id, jobId, pipelineId],
  )
  const editing = useAppSelector(state => isPipelineFormOpened(state, formParams) ?? false)
  const dispatch = useAppDispatch()
  const enableEditing = useCallback(
    () => dispatch(pipelineForm.actions.open(formParams)),
    [dispatch, formParams],
  )
  const disableEditing = useCallback(
    () => dispatch(pipelineForm.actions.close(formParams)),
    [dispatch, formParams],
  )
  const onEditClick = onChangeName != null ? enableEditing : undefined
  const isDisabled = useContext(DisabledContext) || disabled
  const actionsHandlers = useMemo(
    () => [onAddClick, onEditClick, onDeleteClick].filter(action => !!action),
    [onAddClick, onDeleteClick, onEditClick],
  )
  const isTitleUnionAction = useMemo(
    () => actionsHandlers.length === 1 && !collapsible,
    [actionsHandlers, collapsible],
  )
  const titleLabel = !editing ? (
    <span
      className={classNames({
        [styles.deleted]: isDeleted,
      })}
    >
      {[generatedTitle, title].filter(Boolean).join(': ')}
    </span>
  ) : null
  const onKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      if (event.key === 'Enter' || event.key === 'Escape') {
        disableEditing()
      }
    },
    [disableEditing],
  )
  const hoverDetailsIconHandler = (state: boolean) => setDetailsIconHover(state)
  const actionButtons = useMemo(() => {
    const actionButtons = (
      <Actions
        className={styles.actions}
        iconClassName={styles.actionIcon}
        deleted={isDeleted}
        disabled={isDisabled}
        onEditClick={onEditClick}
        onDeleteClick={onDeleteClick}
        onRestoreClick={onRestoreClick}
        onAddClick={onAddClick}
      />
    )
    return customActions ? customActions(actionButtons) : actionButtons
  }, [customActions, isDeleted, isDisabled, onAddClick, onDeleteClick, onEditClick, onRestoreClick])
  const onClickTitle = useMemo(() => {
    const [actionHandler] = actionsHandlers
    if (collapsible) {
      return collapsed ? expand : collapse
    }

    if (isTitleUnionAction && !isReadonly) {
      return actionHandler
    }
    return () => {}
  }, [actionsHandlers, collapse, collapsed, collapsible, expand, isReadonly, isTitleUnionAction])

  return (
    <div className={classNames({[styles.collapsibleContainer]: collapsible})}>
      <div className={styles.header}>
        {draggable && (
          <IconButton
            data-movable-handle
            className={styles.handle}
            icon="drag"
            title="Use drag-and-drop to reorder steps"
          />
        )}
        <H2
          className={classNames(styles.title, {
            [styles.collapsible]: collapsible,
            [styles.titleUnion]: !isReadonly && isTitleUnionAction,
          })}
          onClick={onClickTitle}
        >
          {isReadonly ? (
            <div className={styles.toggle}>{titleLabel}</div>
          ) : collapsible ? (
            <Button
              disabled={isDeleted}
              id={buttonId}
              className={classNames(styles.toggle, {
                [styles.toggleWithEditing]: onChangeName != null,
                [styles.buttonUnhover]: isDetailsIconHover,
              })}
              icon={collapsed ? chevronRightIcon : chevronDownIcon}
              iconClassName={styles.toggleIcon}
              onClick={onClickTitle}
              title={`${collapsed ? 'Expand' : 'Collapse'} ${title || generatedTitle}`}
              aria-expanded={collapsed ? 'false' : 'true'}
              aria-controls={regionId}
            >
              {titleLabel}
              {!editing && details && (
                <HelpDetails onHover={hoverDetailsIconHandler}>{details}</HelpDetails>
              )}
            </Button>
          ) : (
            <React.Fragment>
              {titleLabel}
              {!editing && details && <HelpDetails>{details}</HelpDetails>}
              {isTitleUnionAction && actionButtons}
            </React.Fragment>
          )}
        </H2>
        {editing && (
          <EditSettingsForm onConfirmClick={disableEditing} inline>
            <Input
              className={styles.input}
              size={Size.FULL}
              value={title ?? ''}
              onChange={e => onChangeName?.(e.currentTarget.value)}
              onKeyDown={onKeyDown}
              autoFocus
              aria-label="name"
            />
          </EditSettingsForm>
        )}
        {rightElement && typeof rightElement === 'function' ? rightElement(editing) : rightElement}
        {!editing && !isTitleUnionAction && !isReadonly && actionButtons}
      </div>
      {collapsedNote && collapsed && <div className={styles.collapsedNote}>{collapsedNote}</div>}
      {secondLine}
    </div>
  )
}

export default memo(SettingsBlockHeader)
