import type React from 'react'
import {useCallback, useContext, useMemo} from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../hooks/react-redux'
import {validateField, validateForm} from '../../EditPipelinePage/EditPipelinePage.actions'
import {getPipelineErrorMessage} from '../../EditPipelinePage/EditPipelinePage.selectors'
import {matchError} from '../../utils/validators'

import {ParametersControlContext} from './ParametersControlContext'

function useParametersControl(name: string) {
  const {
    parameters,
    renamedParameters,
    formSpotParamId,
    formErrorSpotId,
    valueHighlightSpotId,
    onNameChange,
    onValueChange,
    onRestore,
    onDelete,
    onConfirm,
  } = useContext(ParametersControlContext)
  const dispatch = useAppDispatch()
  const parameterName = renamedParameters?.[name] ?? name
  const parameterValue = parameters?.[name]
  const parameterNameErrorMessage = useAppSelector(
    getPipelineErrorMessage({...formErrorSpotId, formId: name, fieldName: 'name'}),
  )
  const parameterValueErrorMessage = useAppSelector(
    getPipelineErrorMessage({...formErrorSpotId, formId: name, fieldName: 'value'}),
  )
  const isFormInvalid = useAppSelector(state =>
    state.pipelines.pipelineErrors.some(matchError({...formErrorSpotId, formId: name})),
  )
  const currentParametersName = useMemo(
    () => renamedParameters?.[name] ?? name,
    [name, renamedParameters],
  )
  const changeNameHandler = useCallback(
    ({currentTarget}: React.ChangeEvent<HTMLTextAreaElement>) => {
      onNameChange(currentTarget.value, name)
      dispatch(validateField({...formSpotParamId, id: name}, 'name'))
    },
    [dispatch, formSpotParamId, name, onNameChange],
  )
  const changeValueHandler = useCallback(
    ({currentTarget}: React.ChangeEvent<HTMLTextAreaElement>) => {
      onValueChange(currentTarget.value, name)
      dispatch(validateField({...formSpotParamId, id: name}, 'value'))
    },
    [dispatch, formSpotParamId, name, onValueChange],
  )
  const restoreParametersHandler = useCallback(() => onRestore(name), [name, onRestore])
  const deleteParametersHandler = useCallback(() => onDelete(name), [name, onDelete])
  const confirmParametersHandler = useCallback(() => {
    const isValid = dispatch(validateForm({...formSpotParamId, id: parameterName}))
    onConfirm(isValid, name)
  }, [dispatch, formSpotParamId, name, onConfirm, parameterName])
  const valueHighlightSpot = useMemo(
    () => (valueHighlightSpotId ? {[valueHighlightSpotId]: parameterName} : undefined),
    [parameterName, valueHighlightSpotId],
  )

  return {
    parameters,
    renamedParameters,
    currentParametersName,
    parameterName,
    parameterValue,
    parameterNameErrorMessage,
    parameterValueErrorMessage,
    isFormInvalid,
    valueHighlightSpot,
    changeNameHandler,
    changeValueHandler,
    restoreParametersHandler,
    deleteParametersHandler,
    confirmParametersHandler,
  }
}

export default useParametersControl
