import EditSettingsForm from '../../../../../components/EditSettingsForm/EditSettingsForm'
import Input, {Size} from '../../../../../components/Input'
import {usePipelineId} from '../../../../../hooks/pipeline'
import {pipelineDraft} from '../../../../slices/EditPipelinePage.slices'

import {secretPlaceholder} from './UnityIntegrationForm.consts'

import styles from './UnityIntegrationForm.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

type Props = {
  id?: string
  parameters: Record<string, string | null>
  isAdd?: boolean
  onClose: () => void
}

function UnityIntegrationForm({onClose, id, parameters, isAdd}: Props) {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const setParameters = (newParameters: Record<string, string>) =>
    dispatch(
      pipelineDraft.actions.editIntegration({
        pipelineId,
        id,
        parameters: newParameters,
      }),
    )

  const username = parameters.username ?? ''
  // null means saved secure parameter
  const serialNumber = parameters['secure:serialNumber'] ?? secretPlaceholder
  const password = parameters['secure:password'] ?? secretPlaceholder
  const editSettingsFormTitle = `${isAdd ? 'Add' : 'Edit'} Unity License`

  const deleteHandler = () => {
    dispatch(
      pipelineDraft.actions.deleteIntegration({
        id: id!,
        name: parameters!.displayName!,
        pipelineId,
      }),
    )

    onClose()
  }

  return (
    <EditSettingsForm
      settingsClassName={styles.unityIntegrationForm}
      onConfirmClick={onClose}
      onDeleteClick={deleteHandler}
      title={editSettingsFormTitle}
    >
      <Input
        label={'Serial number'}
        size={Size.FULL}
        data-imitate-password
        value={serialNumber}
        onChange={e => setParameters({'secure:serialNumber': e.currentTarget.value})}
        autoFocus
      />
      <Input
        label={'Username'}
        spellCheck={false}
        size={Size.FULL}
        value={username}
        onChange={e => setParameters({username: e.currentTarget.value})}
      />
      <Input
        label={'Password'}
        size={Size.FULL}
        data-imitate-password
        value={password}
        onChange={e => setParameters({'secure:password': e.currentTarget.value})}
      />
    </EditSettingsForm>
  )
}

export default UnityIntegrationForm
