import {IntegrationType} from '../Integrations.consts'

import DockerIntegrationForm from './DockerIntegrationForm/DockerIntegrationForm'
import NpmIntegrationForm from './NpmIntegrationForm/NpmIntegrationForm'
import UnityIntegrationForm from './UnityIntegrationForm/UnityIntegrationForm'

type Props = {
  id?: string
  type: string
  parameters: Record<string, string | null>
  isAdd?: boolean
  onClose: () => void
}

function IntegrationSettingsForm({type, ...restProps}: Props) {
  return (
    <>
      {type === IntegrationType.NPM && <NpmIntegrationForm {...restProps} />}
      {type === IntegrationType.DOCKER && <DockerIntegrationForm {...restProps} />}
      {type === IntegrationType.UNITY && <UnityIntegrationForm {...restProps} />}
    </>
  )
}

export default IntegrationSettingsForm
