import {memo} from 'react'
import type * as React from 'react'

import {useAppDispatch, useAppSelector} from '../../../../../../hooks/react-redux'
import {ROOT_PROJECT_ID} from '../../../../../../types'
import EditSettingsForm from '../../../components/EditSettingsForm/EditSettingsForm'
import {usePipelineId} from '../../../hooks/pipeline'
import {pipelinesApi} from '../../../services/pipelinesApi'
import {useEditPipelineContext} from '../../EditPipelineContext'
import {validateField, validateForm} from '../../EditPipelinePage.actions'
import {useJobId} from '../../EditPipelinePage.hooks'
import {getPipelineErrors} from '../../EditPipelinePage.selectors'
import {FormType} from '../../slices/EditPipelinePage.slices.types'

import Input, {Size} from 'src/components/pages/PipelinesPages/components/Input'

interface Props {
  currentName: string
  'aria-label'?: string
  onConfirmClick: () => void
  onNameChange: (name: string) => void
}

function NameSectionForm(props: Props) {
  const {currentName, onConfirmClick, onNameChange, 'aria-label': ariaLabel} = props
  const pipelineId = usePipelineId()
  const jobId = useJobId()
  const error = useAppSelector(
    state =>
      getPipelineErrors(state, {
        pipelineId,
        jobId,
        formType: FormType.NAME,
        fieldName: 'name',
      })[0]?.message ?? null,
  )
  const dispatch = useAppDispatch()
  const context = useEditPipelineContext()

  const {data: allPipelines} = pipelinesApi.endpoints.getAllPipelines.useQuery({
    parentProjectId: context.parentProjectId || ROOT_PROJECT_ID,
  })
  const pipelineNames =
    allPipelines?.map(item => ({
      pipelineName: item.name,
      pipelineId: item.id,
    })) ?? []

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    onNameChange(event.currentTarget.value)
    dispatch(validateField({pipelineId, jobId, type: FormType.NAME}, 'name', pipelineNames))
  }

  const handleConfirm = () => {
    const isValid = dispatch(validateForm({pipelineId, jobId, type: FormType.NAME}))
    if (isValid) {
      onConfirmClick()
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === 'Escape') {
      handleConfirm()
      return
    }
  }

  return (
    <EditSettingsForm onConfirmClick={handleConfirm} disabled={Boolean(error)} inline>
      <Input
        size={Size.FULL}
        value={currentName}
        aria-label={ariaLabel}
        onChange={handleNameChange}
        onKeyDown={handleKeyDown}
        error={error}
        autoFocus
        autoComplete="off"
      />
    </EditSettingsForm>
  )
}

export default memo(NameSectionForm)
