import classNames from 'classnames'
import {useMemo, useState} from 'react'

import {
  jsonFormRunnersAvailable,
  jsonFormRunnersAvailableSet,
} from '../../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobSteps/JobStep/JobStepJsonForm/JobStepJsonForm.const'

import styles from './SelectRunner.module.css'

const amountMaxRunnersToShow = 5
const extraPlace = 1
const alwaysFirstRunnerId = 'script'

function useSelectRunner(externalRunners?: string[], selected?: string, className?: string) {
  const runners = useMemo(
    () =>
      (externalRunners
        ? externalRunners.filter(runner => jsonFormRunnersAvailableSet.has(runner))
        : jsonFormRunnersAvailable
      ).toSorted(),
    [externalRunners],
  )
  const [isHiddenRunnerDropdown, setHiddenRunnerDropdown] = useState<boolean>(true)
  const containerClassName = classNames(styles.containerWrapper, className)
  const runnersLength = runners.length
  const hasExtraRunners = runnersLength > amountMaxRunnersToShow
  const amountRunnersToShow = hasExtraRunners
    ? amountMaxRunnersToShow - extraPlace
    : amountMaxRunnersToShow
  const alwaysFirstRunner = runners
    .find(runner => runner.toLowerCase() === alwaysFirstRunnerId)
    ?.toLowerCase()
  const sortedRunners = useMemo(() => {
    const filteredRunners = runners.filter(runner => runner.toLowerCase() !== alwaysFirstRunnerId)
    const runnerstToShow = filteredRunners.slice(0, amountRunnersToShow)
    const isNoSelectIncluded = selected && !runnerstToShow.includes(selected)

    if (isNoSelectIncluded && selected !== alwaysFirstRunnerId) {
      filteredRunners.splice(amountRunnersToShow - 1, 0, selected)

      return filteredRunners
    }

    return filteredRunners
  }, [runners, amountRunnersToShow, selected])
  const runnersToShow = sortedRunners.slice(0, amountRunnersToShow)

  return {
    containerClassName,
    setHiddenRunnerDropdown,
    hasExtraRunners,
    alwaysFirstRunner,
    isHiddenRunnerDropdown,
    amountRunnersToShow,
    sortedRunners,
    runnersToShow,
  }
}

export default useSelectRunner
