import {useMemo, useRef, useState} from 'react'
import {useSearchParams} from 'react-router'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {emptyObject} from '../../../../../../../utils/empty'
import {allBranchesSpecification} from '../../../../components/BranchSpecificationSelect/BranchSpecificationSelect.consts'
import type {pipelineParentProjectFragment$key} from '../../../../hooks/__generated__/pipelineParentProjectFragment.graphql'
import {usePipelineId, usePipelineParentProjectId} from '../../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../../hooks/usePermissionCanEditPipeline'
import {pipelinesApi} from '../../../../services/pipelinesApi'
import type {NewVcsRootDto} from '../../../../services/pipelinesApi.types'
import type {Job} from '../../../../types'
import {validateForm} from '../../../EditPipelinePage.actions'
import {usePipelineAdditionalVcsRootsOrDraft} from '../../../EditPipelinePage.hooks'
import {getDraft, getDraftJobs, getPipelineErrorMessage} from '../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

import {getRepositoryKey} from './PipelineRepository/PipelineRepository.utils'

export const pipelineRepositorySettingsBlockId = 'repositories'
const mainRepositoryName = 'main'

export function useDeletedRepositoriesSet() {
  const pipelineId = usePipelineId()
  const deletedRepositories = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.additionalVcsRoots,
  )
  return useMemo(() => new Set(deletedRepositories), [deletedRepositories])
}

function useDeletedIncompleteRepositoriesSet() {
  const pipelineId = usePipelineId()
  const deletedRepositories = useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.deleted?.incompleteAdditionalVcsRoots,
  )
  return useMemo(() => new Set(deletedRepositories), [deletedRepositories])
}

export function usePipelineRepositories(
  pipelineParentProjectKey: pipelineParentProjectFragment$key | null,
) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const deletingVcsRootsUrl = useRef<string | null>(null)
  const deletingVcsRootsIndex = useRef<number | null>(null)
  const [deletingJobsRepository, setSeletingJobsRepository] = useState<string>('')
  const [isShowDeleteJobConfirmPopup, setShowDeleteJobConfirmPopup] = useState<boolean>(false)
  const mainRepository =
    useAppSelector(state => getDraft(state, pipelineId)?.vcsRoot) ?? (emptyObject as NewVcsRootDto)
  const additionalVcsRoots = usePipelineAdditionalVcsRootsOrDraft()
  const [searchParams, setSearchParams] = useSearchParams()
  const searchParamsObject = Object.fromEntries(searchParams.entries())
  const createdVcsRoots = useMemo(
    () => [mainRepository, ...additionalVcsRoots],
    [additionalVcsRoots, mainRepository],
  )
  const createdRepositories: Set<string> = useMemo(
    () => new Set(createdVcsRoots?.map(({url}) => url)),
    [createdVcsRoots],
  )
  const parentProjectId = usePipelineParentProjectId(pipelineParentProjectKey)
  const {data: vcsProviders} = pipelinesApi.endpoints.getVcsProviders.useQuery({
    parentProjectId: parentProjectId ?? undefined,
  })
  const errorMessage = useAppSelector(
    getPipelineErrorMessage({
      pipelineId,
      formType: FormType.REPOSITORIES,
    }),
  )
  const addRepositoryHandler = canEditPipeline
    ? () => {
        const defaultProvider = vcsProviders?.[0]
        const repositoryIndex = additionalVcsRoots.length
        const id = getRepositoryKey(false, repositoryIndex)

        dispatch(
          pipelineDraft.actions.setAdditionalVcsRoot({
            pipelineId,
            vcsName: 'jetbrains.git', // TODO Why do we use this hardcoded value?
            url: '',
            branch: '',
            branchSpecification: allBranchesSpecification,
            isStatusPublishingEnabled: defaultProvider?.connectionId != null,
            connectionId: defaultProvider?.connectionId,
            vcsProviderType: defaultProvider?.type,
          }),
        )
        dispatch(
          collapsedBlocks.actions.toggle({id: pipelineRepositorySettingsBlockId, collapsed: false}),
        )
        dispatch(
          pipelineForm.actions.open({
            pipelineId,
            id,
            type: FormType.REPOSITORY,
            isAdd: true,
          }),
        )
        setSearchParams({...searchParamsObject, repository: `${id}`})
      }
    : undefined
  const draftJobs = (useAppSelector(state => getDraftJobs(state, pipelineId)) ??
    emptyObject) as Record<string, Job>
  const deleteAdditionalVcsRootHandler = () => {
    const url = deletingVcsRootsUrl.current
    const index = deletingVcsRootsIndex.current
    if (url && index != null) {
      dispatch(
        pipelineErrors.actions.clear({
          pipelineId,
          formType: FormType.REPOSITORY,
          formId: getRepositoryKey(false, index),
        }),
      )
      dispatch(
        pipelineDraft.actions.deleteAdditionalVcsRoot({
          id: pipelineId,
          url,
        }),
      )
      deletingVcsRootsUrl.current = null
      deletingVcsRootsIndex.current = null
      setShowDeleteJobConfirmPopup(false)
    }
  }
  const deleteRepositoryHandler = (url: string, index: number) => () => {
    // Ask about switching the repository to the main if the deleted repo was the last
    const usedJobs = Object.entries(draftJobs).reduce<string[]>((acc, [jobId, value]) => {
      const jobRepositories = value.repositories ?? []
      const repositoriesKeysSet = new Set(
        jobRepositories.flatMap(repository => Object.keys(repository)),
      )
      const isMainRepositoryDisabled = repositoriesKeysSet.has(mainRepositoryName)
      const hasUrlRepositories = repositoriesKeysSet.has(url)
      const isCanDeleted =
        isMainRepositoryDisabled && hasUrlRepositories && repositoriesKeysSet.size === 2

      if (isCanDeleted) {
        acc.push(value?.name ?? jobId)
      }

      return acc
    }, [])

    if (url) {
      deletingVcsRootsUrl.current = url
      deletingVcsRootsIndex.current = index
      if (usedJobs.length) {
        setShowDeleteJobConfirmPopup(true)
        setSeletingJobsRepository(usedJobs.join(', '))
      } else {
        deleteAdditionalVcsRootHandler()
      }
    } else {
      dispatch(
        pipelineErrors.actions.clear({
          pipelineId,
          formType: FormType.REPOSITORY,
          formId: getRepositoryKey(false, index),
        }),
      )
      dispatch(pipelineDraft.actions.deleteIncompleteAdditionalVcsRoot({id: pipelineId, index}))
    }
    dispatch(validateForm({pipelineId, type: FormType.REPOSITORIES}))
  }
  const restoreRepositoryHandler = (url: string) => () => {
    dispatch(
      pipelineDraft.actions.restoreAdditionalVcsRoot({
        id: pipelineId,
        url,
      }),
    )
    dispatch(validateForm({pipelineId, type: FormType.TRIGGER}))
    dispatch(validateForm({pipelineId, type: FormType.REPOSITORIES}))
  }
  const deletedRepositoriesSet = useDeletedRepositoriesSet()
  const deletedIncompleteRepositoriesSet = useDeletedIncompleteRepositoriesSet()
  const shortRepositories = useMemo(
    () => createdVcsRoots.map(({url, branch}) => `${url} Default branch: ${branch}`).join('; '),
    [createdVcsRoots],
  )
  const clickConfirmDeleteJobButtonHandler = () => deleteAdditionalVcsRootHandler()
  const clickRejectDeleteJobButtonHandler = () => {
    setShowDeleteJobConfirmPopup(false)
    deletingVcsRootsUrl.current = null
    deletingVcsRootsIndex.current = null
  }

  const confirmDeleteJobDescription = `This repository is used by the following Job(s): ${deletingJobsRepository}. If you remove it, all repositories that used it will switch to the default (${mainRepository.url}) repository.`

  return {
    additionalVcsRoots,
    deletedRepositoriesSet,
    deletedIncompleteRepositoriesSet,
    shortRepositories,
    mainRepository,
    createdRepositories,
    isShowDeleteJobConfirmPopup,
    confirmDeleteJobDescription,
    errorMessage,
    addRepositoryHandler,
    deleteRepositoryHandler,
    restoreRepositoryHandler,
    clickConfirmDeleteJobButtonHandler,
    clickRejectDeleteJobButtonHandler,
    canEditPipeline,
  }
}
