import {createElement, memo} from 'react'

import type {HighlighterInteralProps, NormalizeTokens} from './Highlighter.types'
import {extractReferences} from './Highlighter.utils'

function HighlighterInteral({children, code, multiline = true}: HighlighterInteralProps) {
  const formattedCode = multiline ? code : code.replace(/(\r\n|\n|\r)/gm, '')
  const tokens: NormalizeTokens[] = formattedCode ? extractReferences(formattedCode) : []

  return children({
    tokens,
  })
}

function Highlighter(props: HighlighterInteralProps) {
  return createElement(memo(HighlighterInteral), props)
}

export default Highlighter
