import classNames from 'classnames'

import type {JobFile} from '../../types'
import Highlighter from '../Highlighter/Highlighter'
import type {NormalizeTokens} from '../Highlighter/Highlighter.types'

import HighlighterTextFieldToken from './HighlighterTextFieldToken'

import styles from './HighlighterTextField.module.css'

type HighlighterTextViewProps = {
  value: JobFile
  multiline?: boolean
  className?: string
}

function HighlighterTextView({value, multiline}: HighlighterTextViewProps) {
  const containerClassNames = classNames(styles.container, {[styles.multiline]: multiline})
  return (
    <Highlighter code={typeof value === 'string' ? value : value.path} multiline={multiline}>
      {({tokens}) => (
        <div className={containerClassNames}>
          {tokens.map(({line, type}: NormalizeTokens, index: number) => {
            const elementKey = `element-${index}`

            return (
              <HighlighterTextFieldToken key={elementKey} line={line} type={type} index={index} />
            )
          })}
        </div>
      )}
    </Highlighter>
  )
}

export default HighlighterTextView
