import type {ReactNode} from 'react'
import {createContext, useContext} from 'react'

type EditPipelineContextType = {
  parentProjectId: Branded<string, 'ProjectId'> | null | undefined
}

const EditPipelineContext = createContext<EditPipelineContextType>({
  parentProjectId: null,
})

type EditPipelineProviderProps = {
  children: ReactNode
  parentProjectId: Branded<string, 'ProjectId'> | null | undefined
}

export function EditPipelineProvider({children, parentProjectId}: EditPipelineProviderProps) {
  return (
    <EditPipelineContext.Provider value={{parentProjectId}}>
      {children}
    </EditPipelineContext.Provider>
  )
}

export const useEditPipelineContext = () => useContext(EditPipelineContext)
