import {useMemo} from 'react'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../hooks/pipeline'
import type {NewIntegrationDto} from '../../../services/pipelinesApi.types'
import {usePipelineIntegrationsOrDraft} from '../../EditPipelinePage.hooks'

import {integrations} from './Integrations.consts'

type Integration = NewIntegrationDto & {
  isDeleted: boolean
}

export function useAvailableIntegrations(): Integration[] {
  const allIntegrations = usePipelineIntegrationsOrDraft()
  const id = usePipelineId()
  const deletedIntegrations = useAppSelector(
    state => state.pipelines.pipelineDraft[id]?.deleted?.integrations,
  )
  return useMemo(
    () =>
      allIntegrations
        ?.filter(({type}) => integrations[type] != null)
        .map(integration => ({
          ...integration,
          isDeleted: deletedIntegrations?.includes(integration.id!) ?? false,
        })) ?? [],
    [allIntegrations, deletedIntegrations],
  )
}
