import Button from '@jetbrains/ring-ui-built/components/button/button'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useEffect, useRef} from 'react'
import type * as React from 'react'

import Tooltip from '../../../../common/Tooltip/Tooltip'

import styles from './EditSettingsForm.module.css'

type Props = {
  className?: string
  settingsClassName?: string
  children: React.ReactNode
  actions?: React.ReactNode
  inline?: boolean
  loader?: boolean
  disabled?: boolean
  scrollIntoView?: boolean
  deleteTitle?: string
  onConfirmClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  onDeleteClick?: (e: React.MouseEvent<HTMLButtonElement>) => void
  onBlur?: () => void
  title?: React.ReactNode
  inputRef?: React.RefObject<HTMLInputElement>
}

function EditSettingsForm({
  children,
  actions,
  inline,
  className,
  settingsClassName,
  loader,
  disabled,
  onBlur,
  deleteTitle = 'Delete',
  onConfirmClick,
  onDeleteClick,
  scrollIntoView = true,
  title,
}: Props) {
  const formRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (
      scrollIntoView &&
      formRef.current &&
      formRef.current.getBoundingClientRect().bottom > window.innerHeight
    ) {
      formRef.current?.scrollIntoView({behavior: 'smooth'})
    }
  }, [scrollIntoView])

  return (
    <div
      ref={formRef}
      className={classNames(styles.editSettingsForm, className, {
        [styles.inline]: inline,
      })}
      onBlur={e => {
        if (!e.currentTarget.contains(e.relatedTarget)) {
          onBlur?.()
        }
      }}
    >
      {title && <div className={styles.title}>{title}</div>}
      <div className={classNames(styles.settings, settingsClassName)}>{children}</div>
      <div className={styles.actions}>
        {onConfirmClick && (
          <Button inline onClick={onConfirmClick} loader={loader} disabled={disabled}>
            {'Done'}
          </Button>
        )}
        {actions}
        {onDeleteClick && (
          <Tooltip delay={100} title={deleteTitle} className={styles.deleteButton}>
            <IconButton
              icon={'trash'}
              title={deleteTitle}
              aria-label={deleteTitle}
              onClick={onDeleteClick}
            />
          </Tooltip>
        )}
      </div>
    </div>
  )
}

export default EditSettingsForm
