import {useCallback, useRef} from 'react'

import type {SuggestionType} from '../../../../../../types'

type SmartDetectorsStore = Record<string, Partial<Record<SuggestionType, Set<string>>>>

const defaultMap = {}

function useJobStepFormProvider() {
  const detectorsDisplayStore = useRef<SmartDetectorsStore>(defaultMap).current
  const getIsDetectorShow = useCallback(
    (jobId: string, detectorKey: SuggestionType, spotId: string) => {
      const isDecoratorShowFirstTime = !detectorsDisplayStore[jobId]?.[detectorKey]
      const isDecoratorShowed = !!detectorsDisplayStore[jobId]?.[detectorKey]?.has(spotId)

      if (isDecoratorShowFirstTime) {
        detectorsDisplayStore[jobId] = {
          [detectorKey]: new Set([spotId]),
        }

        return true
      }

      return isDecoratorShowed
    },
    [detectorsDisplayStore],
  )

  return {
    getIsDetectorShow,
  }
}

export default useJobStepFormProvider
